// Test script to verify credential validity
const { Client } = require('pg');
const https = require('https');
require('dotenv').config({ path: '.env.test' });

// Test database connection
async function testDatabase() {
  console.log('\n🔍 Testing database connection...');

  if (!process.env.DATABASE_URL) {
    console.log('❌ DATABASE_URL not found in environment variables');
    return false;
  }

  const client = new Client({
    connectionString: process.env.DATABASE_URL,
    ssl: false // For testing with internal DB
  });

  try {
    await client.connect();
    const result = await client.query('SELECT NOW()');
    console.log('✅ Database connection successful!');
    console.log('   Timestamp:', result.rows[0].now);
    await client.end();
    return true;
  } catch (error) {
    console.log('❌ Database connection failed:', error.message);
    return false;
  }
}

// Test API key with basic HTTP request
function testApiKey(baseUrl, apiKey, authHeader, successCheck) {
  return new Promise((resolve) => {
    console.log(`\n🔍 Testing ${baseUrl} connection...`);

    if (!apiKey) {
      console.log(`❌ API key not found for ${baseUrl}`);
      resolve(false);
      return;
    }

    const options = {
      hostname: baseUrl,
      path: '/test',
      method: 'GET',
      headers: {
        'Content-Type': 'application/json',
      }
    };

    // Add authentication header
    options.headers[authHeader] = apiKey;

    const req = https.request(options, (res) => {
      let data = '';

      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        if (successCheck(res, data)) {
          console.log(`✅ ${baseUrl} connection successful!`);
          resolve(true);
        } else {
          console.log(`❌ ${baseUrl} request failed:`, res.statusCode, data.substring(0, 100));
          resolve(false);
        }
      });
    });

    req.on('error', (error) => {
      console.log(`❌ ${baseUrl} request error:`, error.message);
      resolve(false);
    });

    // Set timeout
    req.setTimeout(5000, () => {
      req.destroy();
      console.log(`❌ ${baseUrl} request timed out`);
      resolve(false);
    });

    req.end();
  });
}

// Specific test for Anthropic API
async function testAnthropic() {
  return testApiKey(
    'api.anthropic.com',
    process.env.ANTHROPIC_API_KEY,
    'x-api-key',
    (res, data) => {
      // Even with invalid key, Anthropic might return 401 instead of connection error
      return res.statusCode === 401 || res.statusCode === 200 || res.statusCode === 400;
    }
  );
}

// Specific test for AWS (check if credentials format is valid)
async function testAWS() {
  console.log('\n🔍 Testing AWS credentials...');

  if (!process.env.AWS_ACCESS_KEY_ID) {
    console.log('❌ AWS_ACCESS_KEY_ID not found');
    return false;
  }

  if (!process.env.AWS_SECRET_ACCESS_KEY) {
    console.log('❌ AWS_SECRET_ACCESS_KEY not found');
    return false;
  }

  // Check if the keys have the expected format
  const keyIdValid = process.env.AWS_ACCESS_KEY_ID.startsWith('AKIA');
  const keyValid = process.env.AWS_SECRET_ACCESS_KEY.length >= 40;

  if (keyIdValid && keyValid) {
    console.log('✅ AWS credentials format appears valid');
    console.log('   Key ID format: Correct');
    console.log('   Secret length: Valid');
    return true;
  } else {
    console.log('❌ AWS credentials format invalid');
    console.log('   Key ID should start with AKIA');
    console.log('   Secret key should be at least 40 characters');
    return false;
  }
}

// Specific test for Stripe
async function testStripe() {
  return testApiKey(
    'api.stripe.com',
    process.env.STRIPE_SECRET_KEY,
    'Authorization',
    (res, data) => {
      // Stripe returns 401 for invalid keys, 200 for valid
      return res.statusCode === 401 || res.statusCode === 200 || res.statusCode === 400;
    }
  );
}

// Specific test for Logfire
async function testLogfire() {
  return testApiKey(
    'api.logfire.sh',
    process.env.LOGFIRE_TOKEN,
    'Authorization',
    (res, data) => {
      // Look for any successful response or expected error
      return res.statusCode < 500;
    }
  );
}

// Main execution
async function main() {
  console.log('🔐 Credential Validation Test');
  console.log('==========================');

  // Test all credentials
  const results = {
    database: await testDatabase(),
    anthropic: await testAnthropic(),
    aws: await testAWS(),
    stripe: await testStripe(),
    logfire: await testLogfire()
  };

  // Summary
  console.log('\n📋 SUMMARY');
  console.log('========');
  Object.keys(results).forEach(service => {
    console.log(`${service.toUpperCase()}: ${results[service] ? '✅ VALID' : '❌ INVALID'}`);
  });

  const validCount = Object.values(results).filter(Boolean).length;
  const totalCount = Object.keys(results).length;
  console.log(`\n✅ ${validCount}/${totalCount} credentials are valid or have valid format`);

  // Exit with error code if any test failed
  if (validCount < totalCount) {
    process.exit(1);
  }
}

// Run the tests
main().catch(err => {
  console.error('Test failed:', err);
  process.exit(1);
});

