const express = require('express');
const helmet = require('helmet');
const xss = require('xss-clean');
const hpp = require('hpp');

const app = express();

// Security middleware
app.use(helmet()); // Security headers
app.use(xss()); // XSS protection
app.use(hpp()); // HTTP parameter pollution protection

// Rate limiting
const rateLimit = require('express-rate-limit');
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the RateLimit-* headers
  legacyHeaders: false, // Disable the X-RateLimit-* headers
});

// Apply rate limiting to all requests
app.use(limiter);

// Middleware for parsing JSON with size limit
app.use(express.json({ limit: '10kb' }));

// Input validation middleware for users route
const validateUserQuery = (req, res, next) => {
  const { limit, page, sort } = req.query;

  // Validate query parameters
  if (limit && (!Number.isInteger(Number(limit)) || Number(limit) <= 0 || Number(limit) > 100)) {
    return res.status(400).json({
      status: 'error',
      message: 'Limit must be a positive integer between 1 and 100'
    });
  }

  if (page && (!Number.isInteger(Number(page)) || Number(page) <= 0)) {
    return res.status(400).json({
      status: 'error',
      message: 'Page must be a positive integer'
    });
  }

  if (sort && !['name', 'email', 'id'].includes(sort)) {
    return res.status(400).json({
      status: 'error',
      message: 'Sort parameter can only be: name, email, id'
    });
  }

  next();
};

app.get('/health', (req, res) => {
  // Add validation for health check query parameters
  const { verbose } = req.query;

  if (verbose !== undefined && verbose !== 'true' && verbose !== 'false') {
    return res.status(400).json({
      status: 'error',
      message: 'Verbose parameter must be "true" or "false"'
    });
  }

  const healthData = {
    status: 'ok',
    timestamp: new Date().toISOString(),
  };

  // Optional verbose output
  if (verbose === 'true') {
    healthData.environment = process.env.NODE_ENV || 'development';
    healthData.version = '1.0.0'; // In production, get from package.json
  }

  res.json(healthData);
});

app.get('/users', validateUserQuery, (req, res) => {
  try {
    let users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Extract query parameters with defaults
    const limit = parseInt(req.query.limit) || users.length;
    const page = parseInt(req.query.page) || 1;
    const sort = req.query.sort || 'id';

    // Apply sorting
    users.sort((a, b) => {
      if (a[sort] < b[sort]) return -1;
      if (a[sort] > b[sort]) return 1;
      return 0;
    });

    // Apply pagination
    const startIndex = (page - 1) * limit;
    const endIndex = page * limit;
    const paginatedUsers = users.slice(startIndex, endIndex);

    // Return structured response with pagination metadata
    res.json({
      status: 'success',
      results: paginatedUsers.length,
      pagination: {
        current_page: page,
        total_pages: Math.ceil(users.length / limit),
        limit: limit,
        total_results: users.length
      },
      data: {
        users: paginatedUsers
      }
    });

  } catch (error) {
    // Handle unexpected errors
    console.error('Error in /users route:', error);

    res.status(500).json({
      status: 'error',
      message: 'Internal server error'
    });
  }
});

// 404 handler for undefined routes
app.all('*', (req, res, next) => {
  res.status(404).json({
    status: 'error',
    message: `Can\'t find ${req.originalUrl} on this server!`
  });
});

// Global error handling middleware
app.use((err, req, res, next) => {
  console.error('Global error handler:', err);

  const statusCode = err.statusCode || 500;
  const message = err.message || 'Internal server error';

  res.status(statusCode).json({
    status: 'error',
    message: message
  });
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (err) => {
  console.error('UNHANDLED REJECTION! 💥 Shutting down...');
  console.error(err);
  process.exit(1);
});

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('UNCAUGHT EXCEPTION! 💥 Shutting down...');
  console.error(err);
  process.exit(1);
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

