const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

const app = express();

// Security middleware
app.use(helmet());

// Rate limiting to prevent abuse
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.'
});
app.use(limiter);

// Request size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Enhanced health check with error handling
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ 
      status: 'error', 
      message: 'Health check failed'
    });
  }
});

// Users endpoint with input validation (even for simple query params)
app.get('/users', (req, res) => {
  try {
    // Validate query parameters if present
    if (req.query && Object.keys(req.query).length > 0) {
      const validParams = ['limit', 'offset', 'sort'];
      const invalidParams = Object.keys(req.query).filter(param => 
        !validParams.includes(param)
      );

      if (invalidParams.length > 0) {
        return res.status(400).json({
          error: `Invalid query parameters: ${invalidParams.join(', ')}`,
          validParams: validParams
        });
      }

      // Validate parameter values
      if (req.query.limit && (!Number.isInteger(Number(req.query.limit)) || Number(req.query.limit) <= 0)) {
        return res.status(400).json({
          error: 'limit must be a positive integer'
        });
      }
    }

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    res.json(users);

  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({ 
      error: 'Internal server error'
    });
  }
});

// Global error handling middleware
app.use((err, req, res, next) => {
  console.error('Uncaught error:', err);
  res.status(500).json({
    error: 'Something went wrong!'
  });
});

// Handle 404 - endpoint not found
app.use('*', (req, res) => {
  res.status(404).json({
    error: `Cannot ${req.method} ${req.url}`,
    message: 'Endpoint not found'
  });
});

// Improved server startup with error handling
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Handle server errors
server.on('error', (error) => {
  console.error('Server error:', error);
  process.exit(1);
});

// Handle graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully');
  server.close(() => {
    console.log('Process interrupted');
  });
});

module.exports = app;

