const express = require('express');
const app = express();

// Set security headers manually (basic helmet functionality)
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
  next();
});

// Simple rate limiting without external dependencies
const requestCounts = new Map();
const WINDOW_MS = 15 * 60 * 1000; // 15 minutes
const MAX_REQUESTS = 100;

app.use((req, res, next) => {
  const clientIP = req.ip || req.connection.remoteAddress;
  const now = Date.now();

  // Clean up old entries
  for (const [ip, data] of requestCounts) {
    if (now - data.windowStart > WINDOW_MS) {
      requestCounts.delete(ip);
    }
  }

  // Initialize counter for new IPs
  if (!requestCounts.has(clientIP)) {
    requestCounts.set(clientIP, { count: 0, windowStart: now });
  }

  const clientData = requestCounts.get(clientIP);

  // Check if limit exceeded
  if (clientData.count >= MAX_REQUESTS) {
    return res.status(429).json({
      error: 'Too many requests from this IP, please try again later.'
    });
  }

  // Increment counter
  clientData.count++;
  next();
});

// Request size limits
