async function verifyDatabaseConnection() {
  console.log('Testing database connection...');

  try {
    const client = new Client({
      connectionString: process.env.DATABASE_URL,
      ssl: false // For testing with internal DB
    });

    await client.connect();
    const result = await client.query('SELECT NOW()');
    console.log('✅ Database connection successful:', result.rows[0]);
    await client.end();
  } catch (error) {
    console.log('❌ Database connection failed:', error.message);
  }
}

function verifyAPIKey(serviceName, url, apiKeyHeader, apiKeyValue) {
  return new Promise((resolve) => {
    console.log(`\nTesting ${serviceName} API key...`);

    const options = {
      hostname: url.split('/')[0],
      path: '/' + url.split('/').slice(1).join('/'),
      method: 'GET',
      headers: {
        'User-Agent': 'credential-verifier/1.0',
      }
    };

    // Add API key to headers
    if (apiKeyHeader && apiKeyValue) {
      options.headers[apiKeyHeader] = apiKeyValue;
    }

    const req = https.request(options, (res) => {
      let data = '';

      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        if (res.statusCode === 200 || res.statusCode === 401 || res.statusCode === 403) {
          console.log(`✅ ${serviceName} endpoint responded with status: ${res.statusCode}`);
          // 401/403 means the service is reachable, even if auth fails
          resolve(true);
        } else {
          console.log(`❌ ${serviceName} unexpected status: ${res.statusCode}`);
          resolve(false);
        }
      });
    });

    req.on('error', (error) => {
      console.log(`❌ ${serviceName} request failed:`, error.message);
      resolve(false);
    });

    req.setTimeout(10000, () => {
      req.destroy();
      console.log(`❌ ${serviceName} request timed out`);
      resolve(false);
    });

    req.end();
  });
}

