// Generic API key test function
function testApiKey(serviceName, url, apiKey, headers = {}) {
  return new Promise((resolve) => {
    console.log(`Testing ${serviceName} API key...`);

    const requestHeaders = {
      ...headers,
      'User-Agent': 'credential-verifier/1.0'
    };

    if (apiKey) {
      requestHeaders['Authorization'] = `Bearer ${apiKey}`;
    }

    const requestOptions = {
      hostname: url.hostname,
      port: url.port || (url.protocol === 'https:' ? 443 : 80),
      path: url.pathname + url.search,
      method: 'GET',
      headers: requestHeaders,
      rejectUnauthorized: true // Enforce TLS certificate validation
    };

    const req = https.request(requestOptions, (res) => {
      let data = '';

      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        // Success if we get a 2xx status code
        if (res.statusCode >= 200 && res.statusCode < 300) {
          try {
            const jsonData = JSON.parse(data);
            console.log(`${serviceName} response:`, Object.keys(jsonData).length > 0 ? jsonData : 'OK');
            results[serviceName.toLowerCase().replace(/ /g, '_')] = { 
              status: 'VALID', 
              message: `${serviceName} API key is valid`,
              statusCode: res.statusCode
            };
          } catch (e) {
            // Response is valid even if not JSON
            results[serviceName.toLowerCase().replace(/ /g, '_')] = { 
              status: 'VALID', 
              message: `${serviceName} API key is valid (non-JSON response)`,
              statusCode: res.statusCode
            };
          }
        } else {
          // Check for specific authentication/authorization errors
          if (res.statusCode === 401 || res.statusCode === 403) {
            results[serviceName.toLowerCase().replace(/ /g, '_')] = { 
              status: 'INVALID', 
              reason: `Authentication failed - ${res.statusCode} ${res.statusMessage}`,
              statusCode: res.statusCode
            };
          } else {
            results[serviceName.toLowerCase().replace(/ /g, '_')] = { 
              status: 'ERROR', 
              reason: `Service responded with ${res.statusCode} ${res.statusMessage}`,
              statusCode: res.statusCode
            };
          }
        }
        resolve();
      });
    });

    req.on('error', (error) => {
      console.error(`${serviceName} request failed:`, error.message);
      results[serviceName.toLowerCase().replace(/ /g, '_')] = { 
        status: 'FAILED', 
        reason: error.message 
      };
      resolve();
    });

    // Set timeout to prevent hanging
    req.setTimeout(10000, () => {
      req.destroy();
      results[serviceName.toLowerCase().replace(/ /g, '_')] = { 
        status: 'TIMEOUT', 
        reason: 'Request timed out after 10 seconds' 
      };
      resolve();
    });

    req.end();
  });
}

// Test AWS credentials
async function testAwsCredentials() {
  console.log('Testing AWS credentials...');

  const accessKeyId = process.env.AWS_ACCESS_KEY_ID;
  const secretAccessKey = process.env.AWS_SECRET_ACCESS_KEY;

  if (!accessKeyId || !secretAccessKey) {
