// Improved application with security best practices

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const winston = require('winston');

const app = express();

// Security middleware
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"]
    }
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true
  }
}));

// Enable CORS with specific origin
app.use(cors({
  origin: process.env.CORS_ORIGIN || 'https://trusted-domain.com'
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100 // limit each IP to 100 requests per windowMs
});
app.use('/api/', limiter);

// Request logging
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  defaultMeta: { service: 'user-service' },
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' })
  ]
});

if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple()
  }));
}

app.use((req, res, next) => {
  logger.info(`${req.method} ${req.path} ${req.ip}`);
  next();
});

// Parse JSON with size limit
app.use(express.json({
  limit: '10kb'
}));

// Validate health check request
app.get('/health', (req, res) => {
  // Validate query parameters
  if (Object.keys(req.query).length > 0) {
    return res.status(400).json({
      error: 'Health check endpoint does not accept query parameters'
    });
  }

  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString() 
  });
});

// Input validation for users endpoint
app.get('/users', (req, res, next) => {
  try {
    // Validate query parameters
    const { limit, offset } = req.query;

    let validatedLimit = 10;
    let validatedOffset = 0;

    if (limit !== undefined) {
      const parsedLimit = parseInt(limit, 10);
      if (isNaN(parsedLimit) || parsedLimit < 1 || parsedLimit > 100) {
        return res.status(400).json({
          error: 'Limit must be a number between 1 and 100'
        });
      }
      validatedLimit = parsedLimit;
    }

    if (offset !== undefined) {
      const parsedOffset = parseInt(offset, 10);
      if (isNaN(parsedOffset) || parsedOffset < 0) {
        return res.status(400).json({
          error: 'Offset must be a non-negative number'
        });
      }
      validatedOffset = parsedOffset;
    }

    // In a real app, this would query a database with limit and offset
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination
    const paginatedUsers = users.slice(validatedOffset, validatedOffset + validatedLimit);

    res.json({
      data: paginatedUsers,
      pagination: {
        limit: validatedLimit,
        offset: validatedOffset,
        count: paginatedUsers.length,
        total: users.length
      }
    });

  } catch (error) {
    logger.error('Error in /users endpoint:', error);
    next(error);
  }
});

// Error handling middleware
app.use((error, req, res, next) => {
  logger.error(`Uncaught error: ${error.message}`, { stack: error.stack });

  if (res.headersSent) {
    return next(error);
  }

  const status = error.status || 500;
  const message = status === 500 ? 
    'Internal server error' : 
    error.message || 'An error occurred';

  res.status(status).json({
    error: message
  });
});

// Handle 404
app.use('*', (req, res) => {
  res.status(404).json({
    error: `Route ${req.path} not found`
  });
});

// Graceful shutdown
process.on('SIGTERM', () => {
  logger.info('SIGTERM received, shutting down gracefully');
  process.exit(0);
});

process.on('SIGINT', () => {
  logger.info('SIGINT received, shutting down gracefully');
  process.exit(0);
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT}`);
});

module.exports = app;

const winston = {
  createLogger: () => ({
    info: console.log,
    error: console.error,
    add: () => {}
  })
};
module.exports = winston;

/**
 * Configuration module for the application
 * Centralizes all configuration with appropriate defaults and validation
 */

require('dotenv').config();

// Define configuration with validation and defaults
const config = {
  port: validatePort(),
  nodeEnv: process.env.NODE_ENV || 'development',
  isProduction: process.env.NODE_ENV === 'production',
  corsOrigin: process.env.CORS_ORIGIN,

  // Security configuration
  rateLimit: {
    windowMs: 15 * 60 * 1000, // 15 minutes
    max: 100 // limit each IP to 100 requests per windowMs
  },

  // Logging configuration
  logging: {
    level: process.env.LOG_LEVEL || (process.env.NODE_ENV === 'production' ? 'info' : 'debug'),
    logToFile: process.env.LOG_TO_FILE !== 'false' // Can disable file logging if needed
  }
};

function validatePort() {
  const port = process.env.PORT || 3000;
  const portNum = parseInt(port, 10);

  if (isNaN(portNum)) {
    throw new Error(`Invalid port configuration: ${port} is not a number`);
  }

  if (portNum < 1 || portNum > 65535) {
    throw new Error(`Invalid port configuration: ${port} is not a valid port number`);
  }

  return portNum;
}

module.exports = config;

// Mock dotenv for testing
module.exports = {
  config: () => ({})
};

