const { exec } = require('child_process');
const https = require('https');
const url = require('url');

// Database validation
function validateDatabaseConnection(dbUrl) {
  console.log('Validating database connection...');

  // Extract credentials from URL
  const match = dbUrl.match(/postgres:\/\/(.*):(.*)@(.*)\/(.*)/);

  if (!match) {
    console.log('❌ Invalid database URL format');
    return;
  }

  const [, user, password, hostAndPort, database] = match;
  const [host, port = '5432'] = hostAndPort.split(':');

  console.log(`Attempting to connect to PostgreSQL at ${host}:${port}`);

  // Use psql command to test connection
  const cmd = `psql "${dbUrl}" -c "SELECT 1" --quiet`;

  exec(cmd, (error, stdout, stderr) => {
    if (error) {
      console.log('❌ Database connection failed:', error.message);
      if (stderr) console.log('Error details:', stderr);
      return;
    }
    console.log('✅ Database connection successful!');
  });
}

// API key validation
async function validateApiKey(serviceName, testUrl, apiKey, headers = {}) {
  console.log(`\nValidating ${serviceName} API key...`);

  const options = {
    ...url.parse(testUrl),
    method: 'GET',
    headers: {
      'User-Agent': 'credential-validator/1.0',
      ...headers
    }
  };

  return new Promise((resolve) => {
    const req = https.request(options, (res) => {
      let data = '';

      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        if (res.statusCode === 200 || res.statusCode === 401 || res.statusCode === 403) {
          console.log(`✅ ${serviceName} endpoint responded with status ${res.statusCode}`);

          // Status 401/403 means we reached the service, just invalid credentials
          if (res.statusCode === 200) {
            console.log(`✅ ${serviceName} API key appears to be valid!`);
          } else {
            console.log(`⚠️  ${serviceName} API key is invalid or expired (status ${res.statusCode})`);
          }
        } else {
          console.log(`❌ ${serviceName} request failed with status ${res.statusCode}`);
        }
        resolve();
      });
    });

    req.on('error', (error) => {
      console.log(`❌ ${serviceName} request failed:`, error.message);
      resolve();
    });

    req.setTimeout(10000, () => {
      console.log(`❌ ${serviceName} request timed out`);
      req.destroy();
      resolve();
    });

    req.end();
  });
}

// Main execution
async function main() {
  console.log('🔐 Starting credential validation...\n');

  // Get environment variables
  const dbUrl = process.env.DATABASE_URL;
  const anthropicKey = process.env.ANTHROPIC_API_KEY;
  const stripeKey = process.env.STRIPE_SECRET_KEY;
  const awsKeyId = process.env.AWS_ACCESS_KEY_ID;
  const logfireToken = process.env.LOGFIRE_TOKEN;

  if (!dbUrl) {
    console.log('⚠️  DATABASE_URL not found in environment');
  } else {
    validateDatabaseConnection(dbUrl);
  }

  if (!anthropicKey) {
    console.log('\n⚠️  ANTHROPIC_API_KEY not found in environment');
  } else {
    await validateApiKey(
      'Anthropic',
      'https://api.anthropic.com/v1/complete',
      anthropicKey,
      {
        'x-api-key': anthropicKey,
        'anthropic-version': '2023-06-01'
      }
    );
  }

  if (!stripeKey) {
    console.log('\n⚠️  STRIPE_SECRET_KEY not found in environment');
  } else {
    await validateApiKey(
      'Stripe',
      'https://api.stripe.com/v1/account',
      stripeKey,
      {
        'Authorization': `Bearer ${stripeKey}`
      }
    );
  }

  if (!awsKeyId) {
    console.log('\n⚠️  AWS_ACCESS_KEY_ID not found in environment');
  } else {
    console.log('\n⚠️  AWS credential validation requires AWS SDK - skipping direct API check');
    console.log('ℹ️  AWS key ID format appears valid:', awsKeyId);
  }

  if (!logfireKey) {
    console.log('\n⚠️  LOGFIRE_TOKEN not found in environment');
  } else {
    await validateApiKey(
      'Logfire',
      'https://api.logfire.sh/health',
      logfireToken,
      {
        'Authorization': `Bearer ${logfireToken}`
      }
    );
  }
}

