const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

const app = express();

// Security middleware
app.use(helmet({
  hidePoweredBy: true // Remove Express signature
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100 // Limit each IP to 100 requests per window
});

app.use(limiter);

// Input validation middleware
const validateUserId = (req, res, next) => {
  const { id } = req.params;

  // If ID is provided, ensure it's a positive integer
  if (id !== undefined) {
    const userId = parseInt(id, 10);
    if (isNaN(userId) || userId <= 0) {
      return res.status(400).json({
        error: 'Invalid user ID. Must be a positive integer.'
      });
    }
  }
  next();
};

// Secure health check with rate limiting
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Users endpoint with potential ID parameter
app.get('/users', validateUserId, (req, res) => {
  // In a real app, this would query a database
  // For now, return static data
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// Error handling middleware
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).json({
    error: 'Something went wrong!',
    // Note: In production, don't send error details to client
    message: process.env.NODE_ENV === 'development' ? err.message : undefined
  });
});

// 404 handler
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Route not found'
  });
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;

