const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const Joi = require('joi');

const app = express();

// Security middleware
app.use(helmet()); // Security headers

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100 // limit each IP to 100 requests per windowMs
});
app.use(limiter);

// CORS configuration
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS || 'https://yourdomain.com',
  credentials: true
}));

// Body parsing with size limits
app.use(express.json({
  limit: '10kb'
}));
app.use(express.urlencoded({
  extended: true,
  limit: '10kb'
}));

// Timeout for requests
app.use((req, res, next) => {
  req.setTimeout(30000); // 30 seconds
  next();
});

// Input validation schema
const userIdSchema = Joi.number().integer().min(1).max(10000);

// Health check endpoint
app.get('/health', (req, res) => {
  // Add basic authentication check for health endpoint if needed
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    version: process.env.npm_package_version || '1.0.0'
  });
});

// Users endpoint with parameter validation
app.get('/users', (req, res) => {
  try {
    // Validate query parameters
    const { error: queryError, value: query } = Joi.object({
      page: Joi.number().integer().min(1).default(1),
      limit: Joi.number().integer().min(1).max(100).default(10),
      sort: Joi.string().valid('name', 'email', 'id').default('id')
    }).validate(req.query);

    if (queryError) {
      return res.status(400).json({
        error: 'Invalid query parameters',
        details: queryError.details.map(d => d.message)
      });
    }

    // Simulated user data (in real app, this would come from a database)
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination
    const startIndex = (query.page - 1) * query.limit;
    const endIndex = startIndex + query.limit;
    const results = users.slice(startIndex, endIndex);

    res.json({
      data: results,
      pagination: {
        page: query.page,
        limit: query.limit,
        total: users.length,
        pages: Math.ceil(users.length / query.limit)
      }
    });
  } catch (error) {
    console.error('Error in /users endpoint:', error);
    res.status(500).json({
      error: 'Internal server error',
      message: 'An unexpected error occurred'
    });
  }
});

// Single user endpoint (example of parameter validation)
app.get('/users/:id', (req, res) => {
  try {
    // Validate path parameter
    const { error: paramError, value: params } = userIdSchema.validate(req.params.id);

    if (paramError) {
      return res.status(400).json({
        error: 'Invalid user ID',
        details: paramError.details[0].message
      });
    }

    const userId = parseInt(params);

    // Simulated user lookup (in real app, this would query a database)
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find(u => u.id === userId);

    if (!user) {
      return res.status(404).json({
        error: 'User not found'
      });
    }

    res.json(user);
  } catch (error) {
    console.error(`Error fetching user ${req.params.id}:`, error);
    res.status(500).json({
      error: 'Internal server error',
      message: 'An unexpected error occurred'
    });
  }
});

// Global error handling middleware
app.use((err, req, res, next) => {
  console.error('Uncaught error:', err);
  res.status(500).json({
    error: 'Internal server error',
    message: 'An unexpected error occurred'
  });
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Route not found'
  });
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

module.exports = app;

