const express = require('express');
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');
const slowDown = require('express-slow-down');

const app = express();

// Security middleware
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'", "'unsafe-inline'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", "data:", "*.example.com"],
      fontSrc: ["'self'", "data:"]
    }
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// Rate limiting to prevent abuse
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

// Add delay to slow down brute force attacks
const speedLimiter = slowDown({
  windowMs: 15 * 60 * 1000,
  delayAfter: 100,
  delayMs: 500,
});

app.use(limiter);
app.use(speedLimiter);

// Input validation middleware
const validateQueryParams = (req, res, next) => {
  // Clean query parameters to prevent prototype poisoning
  if (req.query.__proto__ || req.query.constructor) {
    return res.status(400).json({
      error: 'Invalid request parameters'
    });
  }
  next();
};

// Error handling middleware
app.use((err, req, res, next) => {
  console.error('Server error:', err);

  // Don't expose internal details in production
  const errorResponse = {
    error: 'Internal server error',
    timestamp: new Date().toISOString()
  };

  // Add request ID for debugging (would be generated earlier in real app)
  if (process.env.NODE_ENV !== 'production') {
    errorResponse.details = err.message;
  }

  res.status(500).json(errorResponse);
});

// Health check with input validation
app.get('/health', validateQueryParams, (req, res) => {
  try {
    // Validate that no unexpected parameters are provided
    const allowedParams = ['cache'];
    const queryParams = Object.keys(req.query);

    if (queryParams.length > 0 && !queryParams.every(param => allowedParams.includes(param))) {
      return res.status(400).json({
        error: 'Invalid query parameter',
        allowed: allowedParams
      });
    }

    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      version: '1.0.0'
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({
      error: 'Health check failed',
      timestamp: new Date().toISOString()
    });
  }
});

// Users endpoint with input validation and sanitization
app.get('/users', validateQueryParams, (req, res) => {
  try {
    // Validate and sanitize query parameters
    let page = 1;
    let limit = 10;

    if (req.query.page) {
      page = parseInt(req.query.page, 10);
      if (isNaN(page) || page < 1) {
        return res.status(400).json({
          error: 'Page must be a positive integer'
        });
      }
    }

    if (req.query.limit) {
      limit = parseInt(req.query.limit, 10);
      // Enforce reasonable limits to prevent abuse
      limit = Math.min(limit, 100);
      if (isNaN(limit) || limit < 1) {
        return res.status(400).json({
          error: 'Limit must be a positive integer'
        });
      }
    }

    // Sample data (in real app, this would come from a database)
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Simple pagination
    const startIndex = (page - 1) * limit;
    const paginatedUsers = users.slice(startIndex, startIndex + limit);

    res.json({
      data: paginatedUsers,
      pagination: {
        page,
        limit,
        total: users.length,
        pages: Math.ceil(users.length / limit)
      },
      timestamp: new Date().toISOString()
    });

  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({
      error: 'Failed to retrieve users',
      timestamp: new Date().toISOString()
    });
  }
});

// Handle 404 routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: `Route ${req.method} ${req.url} not found`,
    timestamp: new Date().toISOString()
  });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

