    res.status(500).json({
      error: 'Failed to retrieve users',
      timestamp: new Date().toISOString()
    });
  }
});

// Handle 404 routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: `Route ${req.method} ${req.url} not found`,
    timestamp: new Date().toISOString()
  });
});

