// SAFE CONNECTION VERIFICATION SCRIPT
// This script checks connectivity without exposing or testing actual credentials
// It's designed to verify configuration without triggering security alerts

const https = require('https');
const url = require('url');
const dns = require('dns');

// Configuration - these should come from environment variables in a real implementation
const CONFIG = {
  // Database host
  DB_HOST: 'db.internal',
  DB_PORT: '5432',

  // API endpoints to check connectivity
  API_ENDPOINTS: [
    'https://api.anthropic.com/health',
    'https://api.stripe.com/v1/account',
    'https://logfire.pydantic.dev/health'
  ]
};

// Check DNS resolution for services
function checkDns(host) {
  return new Promise((resolve) => {
    dns.resolve(host, (err, addresses) => {
      resolve({
        host,
        reachable: !err,
        error: err ? err.message : null,
        addresses: addresses || []
      });
    });
  });
}

// Check if a host:port is open
function checkPort(host, port) {
  return new Promise((resolve) => {
    const socket = new require('net').Socket();

    const timeout = setTimeout(() => {
      socket.destroy();
      resolve({
        host,
        port,
        open: false,
        error: 'Connection timeout'
      });
    }, 5000);

    socket.on('connect', () => {
      clearTimeout(timeout);
      socket.destroy();
      resolve({
        host,
        port,
        open: true,
        error: null
      });
    });

    socket.on('error', (err) => {
      clearTimeout(timeout);
      socket.destroy();
      resolve({
        host,
        port,
        open: false,
        error: err.message
      });
    });

    socket.connect(port, host);
  });
}

// Check HTTP endpoint connectivity (without authentication)
function checkHttp(urlStr) {
  return new Promise((resolve) => {
    const parsedUrl = new url.URL(urlStr);
    const options = {
      hostname: parsedUrl.hostname,
      port: parsedUrl.port || (parsedUrl.protocol === 'https:' ? 443 : 80),
      path: parsedUrl.pathname + parsedUrl.search,
      method: 'GET',
      timeout: 5000,
      // Never send authentication headers
      headers: {}
    };

    const req = https.request(options, (res) => {
      const responseData = [];

      res.on('data', chunk => {
        // Only collect response code, not body content
        responseData.push(chunk);
      });

      res.on('end', () => {
        resolve({
          url: urlStr,
          status: res.statusCode,
          success: res.statusCode < 400,
          error: res.statusCode >= 400 ? `HTTP ${res.statusCode}` : null
        });
      });
    });

    req.on('error', (error) => {
      resolve({
        url: urlStr,
        status: null,
        success: false,
        error: error.message
      });
    });

    req.on('timeout', () => {
      req.destroy();
      resolve({
        url: urlStr,
        status: null,
        success: false,
        error: 'Request timeout'
      });
    });

    req.end();
  });
}

async function verifyConnections() {
  console.log('Starting connection verification...\n');

  // Check database host connectivity
  console.log('1. Checking database host...');
  const dbDns = await checkDns(CONFIG.DB_HOST);
  console.log(`   DNS resolution: ${dbDns.reachable ? '✓' : '✗'} ${dbDns.host}`);
  if (dbDns.error) console.log(`   Error: ${dbDns.error}\n`);

  if (dbDns.reachable) {
    const dbPort = await checkPort(CONFIG.DB_HOST, CONFIG.DB_PORT);
    console.log(`   Port ${CONFIG.DB_PORT}: ${dbPort.open ? '✓' : '✗'}`);
    if (dbPort.error) console.log(`   Error: ${dbPort.error}\n`);
  }

  // Check API endpoints
  console.log('\n2. Checking API endpoints...');
  for (const endpoint of CONFIG.API_ENDPOINTS) {
    console.log(`   Checking ${new url.URL(endpoint).hostname}...`);
    const result = await checkHttp(endpoint);
    console.log(`   ${result.success ? '✓' : '✗'} ${result.url}`);
    if (result.error) console.log(`   Error: ${result.error}`);
    if (result.status) console.log(`   Status: ${result.status}`);
    console.log('');
  }

  console.log('Connection verification complete.');

  // Summary
  const allGood = dbDns.reachable && 
    (dbDns.reachable ? dbPort.open : true) && 
    CONFIG.API_ENDPOINTS.every((_, i) => 
      result => result.success);

  console.log(`\nOverall status: ${allGood ? '✓ All connections appear reachable' : '✗ Some connections may have issues'}`);
}

// Run the verification
if (require.main === module) {
  verifyConnections().catch(console.error);
}

module.exports = { checkDns, checkPort, checkHttp, verifyConnections };

