  const client = new Client({
    host: 'test-db.internal', // Use approved test environment
    port: 5432,
    database: 'test_db',
    user: 'test_user',
    password: 'test_password', // Use non-sensitive test credentials
  });

  try {
    await client.connect();
    console.log('Database connection successful');
    return true;
  } catch (error) {
    console.error('Database connection failed:', error.message);
    return false;
  } finally {
    await client.end();
  }
