const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');

// Security middleware should be applied early
const app = express();

// Security headers
app.use(helmet());

// Rate limiting to prevent abuse
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100 // limit each IP to 100 requests per windowMs
});
app.use(limiter);

// CORS configuration
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true
}));

// Parse JSON with security limits
app.use(express.json({
  limit: '10kb',
  verify: (req, res, buf) => {
    // Add request signature verification if needed
    req.rawBody = buf;
  }
}));

// Timeout for requests
const timeout = require('connect-timeout');
app.use(timeout('30s'));

// Health check - no authentication needed
app.get('/health', (req, res) => {
  // Always succeed, but include basic system info
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
    version: process.env.npm_package_version || '1.0.0'
  });
});

// Input validation middleware
const validateUserId = (req, res, next) => {
  const { id } = req.params;

  // Validate ID is a positive integer
  if (id && (!Number.isInteger(Number(id)) || Number(id) <= 0)) {
    return res.status(400).json({
      error: 'Invalid user ID. Must be a positive integer.',
      code: 'INVALID_ID'
    });
  }

  // Also validate query parameters
  if (req.query.limit && (!Number.isInteger(Number(req.query.limit)) || Number(req.query.limit) <= 0 || Number(req.query.limit) > 100)) {
    return res.status(400).json({
      error: 'Invalid limit parameter. Must be a positive integer between 1 and 100.',
      code: 'INVALID_LIMIT'
    });
  }

  next();
};

// Mock user data - in real app, this would come from a database
const mockUsers = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob', email: 'bob@example.com' },
];

// Get all users with pagination
app.get('/users', (req, res) => {
  try {
    let users = [...mockUsers];

    // Apply pagination if requested
    const limit = req.query.limit ? parseInt(req.query.limit) : users.length;
    const page = req.query.page ? parseInt(req.query.page) : 1;
    const startIndex = (page - 1) * limit;

    users = users.slice(startIndex, startIndex + limit);

    res.json({
      data: users,
      pagination: {
        page,
        limit,
        total: mockUsers.length,
        pages: Math.ceil(mockUsers.length / limit)
      }
    });

  } catch (error) {
    console.error('Error retrieving users:', error);
    res.status(500).json({
      error: 'Internal server error',
      code: 'INTERNAL_ERROR'
    });
  }
});

// Get user by ID
app.get('/users/:id', validateUserId, (req, res) => {
  try {
    const userId = parseInt(req.params.id);
    const user = mockUsers.find(u => u.id === userId);

    if (!user) {
      return res.status(404).json({
        error: `User with ID ${userId} not found`,
        code: 'USER_NOT_FOUND'
      });
    }

    // Remove sensitive data before sending
    const safeUser = { ...user };
    delete safeUser.email; // Example of data minimization

    res.json({ data: safeUser });

  } catch (error) {
    console.error(`Error retrieving user ${req.params.id}:`, error);
    res.status(500).json({
      error: 'Internal server error',
      code: 'INTERNAL_ERROR'
    });
  }
});

// Error handling middleware
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);
  res.status(500).json({
    error: 'Internal server error',
    code: 'INTERNAL_ERROR'
  });
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: `Route ${req.method} ${req.originalUrl} not found`,
    code: 'ROUTE_NOT_FOUND'
  });
});

const PORT = process.env.PORT || 3000;

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  // Graceful shutdown
  process.exit(1);
});

process.on('unhandledRejection', (err) => {
  console.error('Unhandled Rejection:', err);
  // Graceful shutdown
  process.exit(1);
});

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

module.exports = app;
module.exports.server = server;

