const express = require('express');
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');
const cors = require('cors');
const { body, validationResult } = require('express-validator');

const app = express();

// Security middleware
app.use(helmet()); // Sets various HTTP headers for security
app.use(helmet.permittedCrossDomainPolicies()); // Helps prevent clickjacking

// CORS configuration - restrict to known origins in production
app.use(cors({
  origin: process.env.NODE_ENV === 'production' 
    ? ['https://your-allowed-domain.com'] 
    : true
}));

// Rate limiting to prevent abuse
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.'
  }
});
app.use(limiter);

// Request parsing with size limits to prevent DOS
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Input validation middleware for any future endpoints that accept input
const validateUser = [
  body('name').trim().isLength({ min: 1, max: 100 }).withMessage('Name must be 1-100 characters'),
  body('email').isEmail().normalizeEmail().withMessage('Must be a valid email')
];

// Improved health check with error handling
app.get('/health', (req, res) => {
  try {
    res.status(200).json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ 
      error: 'Internal server error',
      timestamp: new Date().toISOString()
    });
  }
});

// Users endpoint with proper error handling
app.get('/users', (req, res) => {
  try {
    // Simulated database call with error handling
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Check if users exist
    if (!users || users.length === 0) {
      return res.status(404).json({
        error: 'No users found',
        timestamp: new Date().toISOString()
      });
    }

    res.status(200).json(users);

  } catch (error) {
    console.error('Error fetching users:', error);
    res.status(500).json({ 
      error: 'Internal server error',
      message: process.env.NODE_ENV === 'production' ? undefined : error.message,
      timestamp: new Date().toISOString()
    });
  }
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Route not found',
    path: req.originalUrl,
    timestamp: new Date().toISOString()
  });
});

// Global error handler (should be last)
app.use((error, req, res, next) => {
  console.error('Unhandled error:', error);

  // Determine status code
  const statusCode = error.statusCode || error.status || 500;

  // Don't leak error details in production
  const errorResponse = {
    error: statusCode === 500 ? 'Internal server error' : error.message,
    timestamp: new Date().toISOString()
  };

  // Add validation errors if present
  if (error.name === 'ValidationError' && process.env.NODE_ENV !== 'production') {
    errorResponse.details = error.errors;
  }

  // Hide technical details in production
  if (process.env.NODE_ENV !== 'production' && statusCode === 500) {
    errorResponse.stack = error.stack;
  }

  res.status(statusCode).json(errorResponse);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received: closing HTTP server');
  // Close server and wait for connections to terminate
  // server.close(() => {
  //   console.log('HTTP server closed');
  // });
});

process.on('SIGINT', () => {
  console.log('SIGINT received: closing HTTP server');
  // server.close(() => {
  //   console.log('HTTP server closed');
  // });
});

// Export port for testing
const PORT = process.env.PORT || 3000;

// Start server
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

// Export app and server for testing
module.exports = { app, server };

