const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

const app = express();

// Security middleware
app.use(helmet()); // Set security headers

// Rate limiting to prevent abuse
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the RateLimit-* headers
  legacyHeaders: false, // Disable the X-RateLimit-* headers
});

// Apply rate limiting to all requests
app.use(limiter);

// Handle JSON parsing errors
app.use(express.json({
  limit: '10kb' // Limit request body size
}));

// Input validation middleware
const validateRequest = (req, res, next) => {
  // Validate query parameters if present
  if (Object.keys(req.query).length > 10) {
    return res.status(400).json({
      error: 'Too many query parameters'
    });
  }

  // Validate parameter values
  for (const [key, value] of Object.entries(req.query)) {
    // Reject parameters that look like prototype pollution attempts
    if (key === '__proto__' || key === 'constructor' || key.includes('__')) {
      return res.status(400).json({
        error: 'Invalid parameter name'
      });
    }

    // Reject excessively long values
    if (typeof value === 'string' && value.length > 1000) {
      return res.status(400).json({
        error: `Parameter ${key} is too long`
      });
    }
  }
  next();
};

// Use validation middleware for all routes
app.use(validateRequest);

// Enhanced health check with error handling
app.get('/health', (req, res) => {
  try {
    // Simulate health checks
    const dependencies = {
