const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const mongoSanitize = require('express-mongo-sanitize');
const xss = require('xss-clean');
const { body, validationResult, query } = require('express-validator');

const app = express();

// Security middleware
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"]
    }
  }
}));

// Remove X-Powered-By header
app.disable('x-powered-by');

// Enable CORS with secure configuration
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per window
  message: {
    error: 'Too many requests from this IP, please try again after 15 minutes',
    code: 'RATE_LIMIT_EXCEEDED'
  },
  standardHeaders: true, // Return rate limit info in the RateLimit-* headers
  legacyHeaders: false, // Disable the X-RateLimit-* headers
});

// Apply rate limit to all requests
app.use(limiter);

// Data sanitization
app.use(mongoSanitize()); // Sanitize data to prevent MongoDB operator injection
app.use(xss()); // Sanitize data to prevent XSS attacks

// Body parsing with limits to prevent abuse
app.use(express.json({
  limit: '10kb', // Limit request body size
  strict: true // Only parse arrays and objects
}));

app.use(express.urlencoded({ 
  extended: true, 
  limit: '10kb' 
}));

// Health check endpoint with input validation
app.get('/health', [
  // Validate query parameters if any
  query('detailed').optional().isBoolean().withMessage('Detailed must be a boolean')
], (req, res) => {
  // Check for validation errors
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ 
      error: 'Validation failed', 
      details: errors.array() 
    });
  }

  const healthData = {
    status: 'ok', 
    timestamp: new Date().toISOString(),
    version: process.env.npm_package_version || '1.0.0'
  };

  // Add detailed info if requested
  if (req.query.detailed === 'true') {
    healthData.environment = process.env.NODE_ENV || 'development';
  }

  res.json(healthData);
});

// Users endpoint with validation and sanitization
app.get('/users', [
  // Validate pagination parameters
  query('page').optional().isInt({ min: 1 }).withMessage('Page must be a positive integer'),
  query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
  query('search').optional().trim().escape().isLength({ max: 50 }).withMessage('Search query too long')
], (req, res) => {
  // Check for validation errors
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ 
      error: 'Validation failed', 
      details: errors.array() 
    });
  }

  // Extract validated query parameters
  const page = parseInt(req.query.page) || 1;
  const limit = parseInt(req.query.limit) || 10;
  const search = req.query.search?.toLowerCase() || '';

  // Sample users data
  let users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // Apply search filter if provided
  if (search) {
    users = users.filter(user => 
      user.name.toLowerCase().includes(search) || 
      user.email.toLowerCase().includes(search)
    );
  }

  // Simple pagination
  const startIndex = (page - 1) * limit;
  const endIndex = page * limit;
  const results = users.slice(startIndex, endIndex);

  // Return paginated response
  res.json({
    data: results,
    pagination: {
      currentPage: page,
      totalPages: Math.ceil(users.length / limit),
      totalResults: users.length,
      hasNext: endIndex < users.length,
      hasPrev: startIndex > 0
    }
  });
});

// Catch 404 for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Route not found',
    path: req.originalUrl,
    code: 'NOT_FOUND'
  });
});

// Global error handling middleware
app.use((error, req, res, next) => {
  // Log error (in production, use a proper logging service)
  console.error('Error:', error);

  // Determine status code
  const statusCode = error.statusCode || error.status || 500;

  // Prepare error response
  const errorResponse = {
    error: process.env.NODE_ENV === 'development' ? error.message : 'Internal server error',
    code: error.code || 'INTERNAL_ERROR',
    timestamp: new Date().toISOString()
  };

  // Add stack trace only in development
  if (process.env.NODE_ENV === 'development') {
    errorResponse.stack = error.stack;
  }

  // Return error response
  res.status(statusCode).json(errorResponse);
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

module.exports = app;

