// Input validation middleware
const validateUserInput = (req, res, next) => {
  // Example validation - can be extended based on requirements
  const { name, email } = req.body;

  if (name && typeof name !== 'string') {
    return next(createError(400, 'Name must be a string'));
  }

  if (name && name.length > 100) {
    return next(createError(400, 'Name is too long'));
  }

  if (email && typeof email !== 'string') {
    return next(createError(400, 'Email must be a string'));
  }

  if (email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    return next(createError(400, 'Invalid email format'));
  }

  next();
};

module.exports = {
  validateUserInput
};

const createError = require('http-errors');

// Centralized error handler middleware
const errorHandler = (err, req, res, next) => {
  // Set default error status and message
  const status = err.status || 500;
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal Server Error'
    : err.message;

  // Log error details (in production, this should go to a logging service)
  console.error('Error:', err);

  // Send response
  res.status(status).json({
    error: {
      message: message,
      status: status
    }
  });
};

// Not found handler
const notFoundHandler = (req, res, next) => {
  next(createError(404, `Cannot ${req.method} ${req.originalUrl}`));
};

module.exports = {
  errorHandler,
  notFoundHandler
};

