const express = require('express');
const helmet = require('helmet');
const cors = require('cors');

const app = express();

// Security middleware
app.use(helmet()); // Security headers
app.use(helmet.hidePoweredBy()); // Hide Express header

// CORS configuration
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',') : ['http://localhost:3000'],
  credentials: true,
}));

// Input validation and sanitization
app.use(express.json({
  limit: '10kb' // Limit request body size
}));

app.use(express.urlencoded({ 
  extended: true, 
  limit: '10kb' 
}));

// Request logging
app.use((req, res, next) => {
  console.log(`${new Date().toISOString()} - ${req.method} ${req.path} from ${req.ip}`);
  next();
});

// Rate limiting (basic implementation)
const requestCounts = new Map();
const RATE_LIMIT_WINDOW = 60 * 1000; // 1 minute
const MAX_REQUESTS = 100; // per window

app.use((req, res, next) => {
  const clientIp = req.ip;
  const now = Date.now();

  // Clean old entries
  if (requestCounts.size > 1000) {
    for (const [ip, data] of requestCounts) {
      if (now - data.windowStart > RATE_LIMIT_WINDOW * 2) {
        requestCounts.delete(ip);
      }
    }
  }

  const clientData = requestCounts.get(clientIp) || { count: 0, windowStart: now };

  // Reset counter if outside current window
  if (now - clientData.windowStart > RATE_LIMIT_WINDOW) {
    clientData.count = 0;
    clientData.windowStart = now;
  }

  clientData.count++;
  requestCounts.set(clientIp, clientData);

  // Check rate limit
  if (clientData.count > MAX_REQUESTS) {
    return res.status(429).json({
      error: 'Rate limit exceeded. Please try again later.',
      retryAfter: RATE_LIMIT_WINDOW - (now - clientData.windowStart)
    });
  }

  next();
});

// Health check with better error handling
app.get('/health', (req, res) => {
  try {
    // Simulate basic health checks
    const healthChecks = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      memory: process.memoryUsage()
    };

    res.json(healthChecks);
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({
      error: 'Health check failed',
      timestamp: new Date().toISOString()
    });
  }
});

// Input validation for user queries
function validateUserId(id) {
  const numId = parseInt(id, 10);
  return {
    isValid: !isNaN(numId) && numId > 0,
    value: numId
  };
}

// Secure user endpoint with input validation
app.get('/users', (req, res) => {
  try {
    // Mock database
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Handle query parameters securely
    const { id, name } = req.query;

    let filteredUsers = users;

    // Filter by ID if provided
    if (id !== undefined) {
      const validation = validateUserId(id);
      if (!validation.isValid) {
        return res.status(400).json({
          error: 'Invalid user ID. Must be a positive integer.',
          example: '/users?id=1'
        });
      }

      filteredUsers = filteredUsers.filter(user => user.id === validation.value);

      // Return 404 if no user found
      if (filteredUsers.length === 0) {
        return res.status(404).json({
          error: `User with ID ${validation.value} not found`
        });
      }
    }

    // Filter by name if provided
    if (name !== undefined) {
      // Input sanitization - convert to string and trim
      const nameStr = String(name).trim();

      // Validate input length
      if (nameStr.length === 0) {
        return res.status(400).json({
          error: 'Name parameter cannot be empty'
        });
      }

      if (nameStr.length > 100) {
        return res.status(400).json({
          error: 'Name parameter too long'
        });
      }

      // Simple case-insensitive search
      filteredUsers = filteredUsers.filter(user => 
        user.name.toLowerCase().includes(nameStr.toLowerCase())
      );

      // Return 404 if no users found
      if (filteredUsers.length === 0) {
        return res.status(404).json({
          error: `No users found matching name: ${nameStr}`
        });
      }
    }

    // Sanitize output - remove sensitive data if needed
    const sanitizedUsers = filteredUsers.map(({ id, name, email }) => ({
      id,
      name,
      // Don't expose full email in some contexts
      email: process.env.NODE_ENV === 'production' ? 
        email.replace(/(.)(.*)(@.*)/, (_, a, b, c) => 
          a + '*'.repeat(b.length) + c) : 
        email
    }));

    res.json(sanitizedUsers);
  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({
      error: 'Internal server error',
      message: process.env.NODE_ENV === 'production' ? 
        'An error occurred' : error.message
    });
  }
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: `Route ${req.method} ${req.path} not found`,
    availableRoutes: [
      '/health',
      '/users'
    ]
  });
});

// Global error handler
app.use((error, req, res, next) => {
  console.error('Unhandled error:', error);

  // Handle specific error types
  if (error.name === 'ValidationError') {
    return res.status(400).json({
      error: 'Validation error',
      message: error.message
    });
  }

  if (error.name === 'UnauthorizedError') {
    return res.status(401).json({
      error: 'Unauthorized',
      message: 'Authentication required'
    });
  }

  res.status(500).json({
    error: 'Internal server error',
    message: process.env.NODE_ENV === 'production' ? 
      'An error occurred' : error.message
  });
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  process.exit(0);
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully');
  process.exit(0);
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
  console.log(`Health check: http://localhost:${PORT}/health`);
  console.log(`Users: http://localhost:${PORT}/users`);
});

// Set timeout to prevent hanging connections
server.timeout = 30000; // 30 seconds

module.exports = app;

