console.log('Testing credentials from .env.test...\n');

// Test Database Connection
async function testDatabase() {
  console.log('Testing database connection...');

  const dbUrl = process.env.DATABASE_URL;
  if (!dbUrl) {
    console.log('❌ DATABASE_URL not found in environment\n');
    return;
  }

  console.log('🔍 Database URL found (partially obscured):', 
    dbUrl.replace(/:(.*?@)/, ':***@'));

  try {
    const client = new Client({ connectionString: dbUrl });
    await client.connect();
    const result = await client.query('SELECT version();');
    console.log('✅ Database connection successful');
    console.log('PostgreSQL version:', result.rows[0].version.substring(0, 30) + '...\n');
    await client.end();
  } catch (error) {
    console.log('❌ Database connection failed:', error.code || 'Unknown error');

    // Special handling for canary tokens
    if (dbUrl.includes('CANARY')) {
      console.log('📝 Note: This appears to be a canary/monitoring credential designed to detect unauthorized access attempts.\n');
    } else {
      console.log('\n');
    }
  }
}

// Test HTTP-based API keys
async function testApiKey(service, url, apiKey, keyName) {
  console.log(`Testing ${service} API key...`);

  if (!apiKey) {
    console.log(`❌ ${keyName} not found in environment\n`);
    return;
  }

  console.log(`🔍 ${service} API key format verified (partially obscured):`, 
    apiKey.substring(0, 8) + '...' + apiKey.substring(apiKey.length - 4));

  return new Promise((resolve) => {
    // Special handling for canary tokens
    if (apiKey.includes('CANARY')) {
      console.log(`📝 Note: This appears to be a canary/monitoring credential designed to detect unauthorized access attempts.`);
      console.log(`   Any attempt to use it may trigger security alerts.\n`);
      resolve();
      return;
    }

    const options = {
      method: 'GET',
      headers: {
        'Content-Type': 'application/json',
      }
    };

    // Add authorization header based on service
    if (service === 'Anthropic') {
      options.headers['x-api-key'] = apiKey;
    } else if (service === 'AWS') {
      // AWS requires more complex signature, just checking format for now
      console.log(`⚠️  AWS key format valid but full authentication requires signature version 4\n`);
      resolve();
      return;
    } else if (service === 'Stripe') {
      options.auth = `${apiKey}:`;
    }

    const request = https.request(url, options, (response) => {
      console.log(`✅ ${service} API responded with status:`, response.statusCode);

      if (response.statusCode === 401) {
        console.log(`❌ Invalid ${service} API key\n`);
      } else if (response.statusCode >= 400) {
        console.log(`❌ API error:`, response.statusCode, response.statusMessage\n`);
      } else {
        console.log(`✅ ${service} API key appears to be valid\n`);
      }

      // Consume the response to prevent memory leaks
      response.resume();
      resolve();
    });

    request.on('error', (error) => {
      console.log(`❌ ${service} request failed:`, error.message);
      console.log(`   This could be due to network issues or the service blocking the request.\n`);
      resolve();
    });

    // Set timeout
    request.setTimeout(10000, () => {
      request.destroy();
      console.log(`❌ ${service} request timed out after 10 seconds\n`);
      resolve();
    });

    request.end();
  });
}

