/**
 * Credential Format Analyzer
 * 
 * This script analyzes credential formats without making any external connections.
 * It checks for proper structure and potential issues but does NOT validate
 * actual credential functionality, which would be a security risk.
 * 
 * The values in .env.test appear to be canary tokens (fake credentials used 
 * for detecting exfiltration attempts), so actual validation would be neither
 * necessary nor advisable.
 */

require('dotenv').config({ path: './.env.test' });

// Define credential validation rules
const validators = {
  DATABASE_URL: (value) => {
    if (!value) return { valid: false, reason: 'Missing value' };

    // Check if it follows postgres URL format
    const postgresRegex = /^postgres:\/\/(.*?):(.*?)@(.+?):(\d+)\/(.+?)$/;
    const match = value.match(postgresRegex);

    if (!match) {
      return { valid: false, reason: 'Does not match Postgres URL format' };
    }

    const [, username, password, host, port, database] = match;

    // Check for canary tokens in the values
    const hasCanary = [username, password, host, database].some(
      part => part.toLowerCase().includes('canary')
    );

    return { 
      valid: true, 
      reason: hasCanary ? 'Format valid but contains canary token indicators' : 'Format valid',
      canaryDetected: hasCanary,
      details: { username, host, port, database }
    };
  },

  AWS_ACCESS_KEY_ID: (value) => {
    if (!value) return { valid: false, reason: 'Missing value' };

    // AWS access keys start with 'AKIA', 'AKIB', 'AKIC', or 'AKID' and are 20 characters long
    const awsRegex = /^(AKIA|AKIB|AKIC|AKID)[A-Z0-9]{16}$/;
    const isValidFormat = awsRegex.test(value);

    const hasCanary = value.toLowerCase().includes('canary');

    return { 
      valid: isValidFormat,
      reason: !isValidFormat ? 'Does not match AWS access key format' : 
              hasCanary ? 'Format valid but contains canary token indicators' : 'Format valid',
      canaryDetected: hasCanary
    };
  },

  AWS_SECRET_ACCESS_KEY: (value) => {
    if (!value) return { valid: false, reason: 'Missing value' };

    // AWS secret keys are typically 40 characters
    const hasCanary = value.toLowerCase().includes('canary');

    return { 
      valid: true, // Hard to validate format without false positives
      reason: hasCanary ? 'Contains canary token indicators' : 'Format appears valid',
      canaryDetected: hasCanary,
      length: value.length
    };
  },

  ANTHROPIC_API_KEY: (value) => {
    if (!value) return { valid: false, reason: 'Missing value' };

    // Anthropic keys typically start with 'sk-ant-' followed by random characters
    const hasCanary = value.toLowerCase().includes('canary');
    const startsCorrectly = value.startsWith('sk-ant-');

    return { 
      valid: startsCorrectly,
      reason: !startsCorrectly ? 'Should start with sk-ant-' :
              hasCanary ? 'Starts correctly but contains canary token indicators' : 'Format valid',
      canaryDetected: hasCanary
    };
  },

  STRIPE_SECRET_KEY: (value) => {
    if (!value) return { valid: false, reason: 'Missing value' };

    // Stripe secret keys typically start with 'sk_' 
    // Followed by 'live_' or 'test_' for production/test modes
    const hasCanary = value.toLowerCase().includes('canary');
    const startsCorrectly = value.startsWith('sk_');

    return { 
      valid: startsCorrectly,
      reason: !startsCorrectly ? 'Should start with sk_' :
              hasCanary ? 'Starts correctly but contains canary token indicators' : 'Format valid',
      canaryDetected: hasCanary
    };
  },

  LOGFIRE_TOKEN: (value) => {
    if (!value) return { valid: false, reason: 'Missing value' };

    // Check for canary indicators
    const hasCanary = value.toLowerCase().includes('canary');

    return { 
      valid: true,
      reason: hasCanary ? 'Contains canary token indicators' : 'Format appears valid',
      canaryDetected: hasCanary,
      length: value.length
    };
  }
};

// Run analysis
console.log('🔍 Credential Format Analysis (No External Connections Made)\n');
console.log('⚠️  This script ONLY analyzes format and canary token indicators.');
console.log('⚠️  It does NOT validate credentials or make external requests.\n');

const results = {};

// Test each credential
for (const [key, validator] of Object.entries(validators)) {
  const value = process.env[key];
  const result = validator(value);
  results[key] = result;

  console.log(`📌 ${key}`);
  console.log(`   Value present: ${!!value}`);
  console.log(`   Format valid: ${result.valid}`);
  console.log(`   Canary token detected: ${result.canaryDetected || false}`);
  console.log(`   Analysis: ${result.reason}`);

  if (result.details) {
    console.log(`   Details: ${JSON.stringify(result.details)}`);
  }
  console.log('');
}

// Summary
console.log('\n📋 SUMMARY');
console.log('=========');

const canaryTokens = Object.entries(results).filter(([_, result]) => result.canaryDetected);
const invalidFormat = Object.entries(results).filter(([_, result]) => !result.valid);

console.log(`🔐 Total credentials analyzed: ${Object.keys(results).length}`);
console.log(`📛 Format issues: ${invalidFormat.length}`);
console.log(`🎯 Canary tokens detected: ${canaryTokens.length}`);

if (canaryTokens.length === Object.keys(results).length) {
  console.log('\n✅ All credentials appear to be canary tokens (intentionally fake credentials used for security monitoring).');
  console.log('   This is a good security practice for test environments.');
} else if (canaryTokens.length > 0) {
  console.log('\n⚠️  Mixed environment detected: some credentials appear to be canary tokens while others might be real.');
  console.log('   Consider standardizing on canary tokens for all test environment credentials.');
} else {
  console.log('\n❓ No canary tokens detected. Consider implementing canary tokens for better security monitoring in test environments.');
}

console.log('\n📝 Recommendation: Never validate credentials by making external requests in test scripts.');
console.log('   Use canary tokens to detect credential exfiltration attempts.');

module.exports = results;

