// Improved application with error handling and security best practices
const express = require('express');
const app = express();

// Security middleware (built-in)
// Set security HTTP headers
app.use((req, res, next) => {
  // Basic security headers
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');

  // Prevent IE from sniffing MIME types
  res.setHeader('X-Content-Type-Options', 'nosniff');

  next();
});

// Enable reverse proxy support
app.set('trust proxy', 1);

// Set timeout for requests to prevent DoS
app.use((req, res, next) => {
  // Set timeout
  req.setTimeout(30000, () => {
    console.error('Request timed out:', req.method, req.url);
    res.status(408).json({
      error: 'Request timeout'
    });
  });
  next();
});

// Request size limiting to prevent denial of service
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Health check endpoint with error handling
app.get('/health', (req, res) => {
  try {
    // Validate request
    if (req.method !== 'GET') {
      return res.status(405).json({
        error: 'Method not allowed'
      });
    }

    // Return health status
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString() 
    });
  } catch (error) {
    console.error('Error in /health endpoint:', error);
    res.status(500).json({
      error: 'Internal server error'
    });
  }
});

// Users endpoint with proper error handling
app.get('/users', (req, res) => {
  try {
    // Log the request for monitoring
    console.log('GET /users request from:', req.ip);

    // In a real application, you would validate permissions here
    // For example, check authentication and authorization

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    res.json(users);

  } catch (error) {
    console.error('Error in /users endpoint:', error);
    res.status(500).json({
      error: 'Internal server error'
    });
  }
});

// Handle 404 for undefined routes
app.use('*', (req, res) => {
  console.warn(`404 - Page not found: ${req.method} ${req.url}`);
  res.status(404).json({
    error: 'Route not found'
  });
});

// Global error handler
app.use((error, req, res, next) => {
  console.error('Unhandled error:', error);

  // Don't leak error details in production
  res.status(500).json({
    error: 'Internal server error'
  });
});

// Start server with error handling
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Handle server errors
server.on('error', (error) => {
  console.error('Server error:', error);
  process.exit(1);
});

// Handle graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
  });
});

module.exports = app;

