const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const Joi = require('joi');

const app = express();

// Security middleware
app.use(helmet());

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again after 15 minutes'
});
app.use(limiter);

// CORS configuration
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS || ['http://localhost:3000'],
  credentials: true
}));

// Error handling middleware
app.use((err, req, res, next) => {
  console.error('Server Error:', err.stack);

  // Don't leak sensitive information in production
  const errorResponse = {
    message: 'An internal server error occurred',
    timestamp: new Date().toISOString()
  };

  if (process.env.NODE_ENV !== 'production') {
    errorResponse.stack = err.stack;
  }

  res.status(err.status || 500).json(errorResponse);
});

// Input validation schema for query parameters
const healthQuerySchema = Joi.object({
  // Add any allowed query parameters here
  // Example: format: Joi.string().valid('json', 'xml')
}).options({ stripUnknown: true });

const usersQuerySchema = Joi.object({
  limit: Joi.number().integer().min(1).max(100).default(10),
  offset: Joi.number().integer().min(0).default(0),
  sort: Joi.string().valid('name', 'email', 'id').default('name'),
  order: Joi.string().valid('asc', 'desc').default('asc')
}).options({ stripUnknown: true });

// Health endpoint with input validation
app.get('/health', (req, res, next) => {
  try {
    // Validate query parameters
    const { error: validationError, value } = healthQuerySchema.validate(req.query);

    if (validationError) {
      return res.status(400).json({
        message: 'Invalid query parameters',
        error: validationError.details.map(d => d.message),
        timestamp: new Date().toISOString()
      });
    }

    // Use validated values
    const result = { 
      status: 'ok', 
      timestamp: new Date().toISOString() 
    };

    res.json(result);
  } catch (error) {
    next(error);
  }
});

// Users endpoint with input validation
app.get('/users', (req, res, next) => {
  try {
    // Validate query parameters
    const { error: validationError, value } = usersQuerySchema.validate(req.query);

    if (validationError) {
      return res.status(400).json({
        message: 'Invalid query parameters',
        error: validationError.details.map(d => d.message),
        timestamp: new Date().toISOString()
      });
    }

    // Use validated values for filtering/sorting
    const { limit, offset, sort, order } = value;

    // Mock data (in real app, this would come from a database)
    let users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply sorting
    users.sort((a, b) => {
      if (order === 'asc') {
        return a[sort] > b[sort] ? 1 : -1;
      } else {
        return a[sort] < b[sort] ? 1 : -1;
      }
    });

    // Apply pagination
    const paginatedUsers = users.slice(offset, offset + limit);

    res.json({
      data: paginatedUsers,
      pagination: {
        limit,
        offset,
        total: users.length,
        next_offset: offset + limit < users.length ? offset + limit : null
      },
      timestamp: new Date().toISOString()
    });
  } catch (error) {
    next(error);
  }
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    message: `Route ${req.method} ${req.url} not found`,
    timestamp: new Date().toISOString()
  });
});

// Start server
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);

  // Log security notice in development
  if (process.env.NODE_ENV !== 'production') {
    console.log('Security features enabled: Helmet, Rate Limiting, CORS');
  }
});

// Handle server errors
server.on('error', (error) => {
  console.error('Server startup error:', error);
  process.exit(1);
});

module.exports = app;

