const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const xss = require('xss-clean');
const hpp = require('hpp');

const app = express();

// Security middleware
app.use(helmet()); // Set security HTTP headers

// Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the RateLimit-* headers
  legacyHeaders: false, // Disable the X-RateLimit-* headers
});

app.use('/api/', limiter);

// Enable CORS with security restrictions
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS || 'https://yourdomain.com',
  credentials: true,
}));

// Data sanitization against XSS
app.use(xss());

// Prevent parameter pollution
app.use(hpp());

// Body parsing with limits to prevent abuse
app.use(express.json({
  limit: '10kb' // Limit request body size
}));

// Input validation middleware
const validateQueryParams = (req, res, next) => {
  // Validate known query parameters
  const allowedParams = ['limit', 'page', 'sort', 'filter'];
  const requestParams = Object.keys(req.query);

  for (const param of requestParams) {
    if (!allowedParams.includes(param)) {
      return res.status(400).json({
        error: `Invalid query parameter: ${param}`
      });
    }
  }

  // Validate parameter values
  if (req.query.limit && (!Number.isInteger(Number(req.query.limit)) || Number(req.query.limit) <= 0)) {
    return res.status(400).json({
      error: 'Limit must be a positive integer'
    });
  }

  next();
};

// Health check endpoint
app.get('/health', validateQueryParams, (req, res) => {
  // Additional input validation for query parameters
  const allowedStatus = ['full', 'basic'];
  const status = req.query.status || 'basic';

  if (status && !allowedStatus.includes(status)) {
    return res.status(400).json({
      error: `Status must be one of: ${allowedStatus.join(', ')}`
    });
  }

  try {
    const healthResponse = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      version: process.env.npm_package_version || '1.0.0'
    };

    // Add extended info for full status
    if (status === 'full') {
      healthResponse.process = {
        memory: process.memoryUsage(),
        uptime: process.uptime()
      };
    }

    res.json(healthResponse);
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({
      error: 'Internal server error'
    });
  }
});

// Users endpoint with input validation
app.get('/users', validateQueryParams, (req, res) => {
  try {
    // Mock data - in a real app, this would come from a database
    const mockUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Handle pagination
    const page = parseInt(req.query.page) || 1;
    const limit = Math.min(parseInt(req.query.limit) || 10, 100); // Cap at 100
    const startIndex = (page - 1) * limit;
    const endIndex = page * limit;

    // Validate pagination parameters
    if (page < 1 || limit < 1) {
      return res.status(400).json({
        error: 'Page and limit must be positive numbers'
      });
    }

    // Simulate pagination
    const results = {};
    if (endIndex < mockUsers.length) {
      results.next = {
        page: page + 1,
        limit: limit
      };
    }

    if (startIndex > 0) {
      results.previous = {
        page: page - 1,
        limit: limit
      };
    }

    results.results = mockUsers.slice(startIndex, endIndex);
    results.total = mockUsers.length;
    results.page = page;
    results.limit = limit;

    res.json(results);
  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({
      error: 'Internal server error'
    });
  }
});

// Handle 404 for undefined routes
app.all('*', (req, res) => {
  res.status(404).json({
    error: `Can't find ${req.originalUrl} on this server!`
  });
});

// Global error handling middleware
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Don't leak error details in production
  const isProd = process.env.NODE_ENV === 'production';

  res.status(err.statusCode || 500).json({
    error: isProd ? 'Internal server error' : err.message,
    ...(isProd ? {} : { stack: err.stack }) // Include stack trace only in development
  });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

