const express = require('express');
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const hpp = require('hpp');

const app = express();

// Security middleware
app.use(helmet()); // Set security headers
app.use(xss()); // Prevent XSS attacks
app.use(mongoSanitize()); // Prevent MongoDB query injection
app.use(hpp()); // Prevent HTTP parameter pollution

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the RateLimit-* headers
  legacyHeaders: false, // Disable the X-RateLimit-* headers
});

// Apply rate limiter to all requests
app.use(limiter);

// Middleware for parsing JSON with size limit
app.use(express.json({
  limit: '10kb' // Limit request body size
}));

// Request logging middleware
app.use((req, res, next) => {
  console.log(`${new Date().toISOString()} - ${req.method} ${req.path}`);
  next();
});

// Health check endpoint with error handling
app.get('/health', (req, res) => {
  try {
    // Validate query parameters if present
    if (Object.keys(req.query).length > 0) {
      const allowedParams = ['format'];
      const invalidParams = Object.keys(req.query).filter(param => !allowedParams.includes(param));

      if (invalidParams.length > 0) {
        return res.status(400).json({
          error: 'Invalid query parameters',
          details: `The following parameters are not allowed: ${invalidParams.join(', ')}
        });
      }
    }

    const healthData = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
    };

    if (req.query.format === 'detailed') {
      healthData.hostname = require('os').hostname();
      healthData.platform = process.platform;
      healthData.version = process.version;
    }

    res.json(healthData);
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({
      error: 'Internal server error',
      message: 'Failed to retrieve health status'
    });
  }
});

// Users endpoint with input validation
app.get('/users', (req, res) => {
  try {
    // Input validation
    const { limit, page, sort } = req.query;

    // Validate and sanitize query parameters
    let validatedLimit = 10; // default limit
    let validatedPage = 1; // default page
    let validatedSort = 'id'; // default sort

    if (limit) {
      const numLimit = parseInt(limit);
      if (isNaN(numLimit) || numLimit < 1 || numLimit > 100) {
        return res.status(400).json({
          error: 'Invalid limit parameter',
          message: 'Limit must be a number between 1 and 100'
        });
      }
      validatedLimit = numLimit;
    }

    if (page) {
      const numPage = parseInt(page);
      if (isNaN(numPage) || numPage < 1) {
        return res.status(400).json({
          error: 'Invalid page parameter',
          message: 'Page must be a positive number'
        });
      }
      validatedPage = numPage;
    }

    if (sort) {
      const allowedSorts = ['id', 'name', 'email'];
      if (!allowedSorts.includes(sort)) {
        return res.status(400).json({
          error: 'Invalid sort parameter',
          message: `Sort must be one of: ${allowedSorts.join(', ')}`
        });
      }
      validatedSort = sort;
    }

    // Mock user data
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      { id: 4, name: 'Diana', email: 'diana@example.com' },
      { id: 5, name: 'Eve', email: 'eve@example.com' }
    ];

    // Apply sorting
    const sortedUsers = [...users].sort((a, b) => {
      if (a[validatedSort] < b[validatedSort]) return -1;
      if (a[validatedSort] > b[validatedSort]) return 1;
      return 0;
    });

    // Apply pagination
    const startIndex = (validatedPage - 1) * validatedLimit;
    const paginatedUsers = sortedUsers.slice(startIndex, startIndex + validatedLimit);

    // Return response with metadata
    res.json({
      data: paginatedUsers,
      pagination: {
        total: users.length,
        pages: Math.ceil(users.length / validatedLimit),
        page: validatedPage,
        limit: validatedLimit,
        hasPrevious: validatedPage > 1,
        hasNext: validatedPage < Math.ceil(users.length / validatedLimit)
      }
    });

  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({
      error: 'Internal server error',
      message: 'Failed to retrieve users'
    });
  }
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Route not found',
