const express = require('express');
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');
const cors = require('cors');
const Joi = require('joi');

const app = express();

// Security middleware
app.use(helmet()); // Security headers

// CORS configuration - restrict to known origins in production
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',') : ['http://localhost:3000'],
  credentials: true
}));

// Rate limiting to prevent DDoS
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per window
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the RateLimit-* headers
  legacyHeaders: false // Disable the X-RateLimit-* headers
});
app.use(limiter);

// Body parsing with size limits to prevent abuse
app.use(express.json({
  limit: '10kb',
  extended: true
}));

app.use(express.urlencoded({
  limit: '10kb',
  extended: true
}));

// Request timeout
app.use((req, res, next) => {
  req.setTimeout(30000, () => { // 30 second timeout
    res.status(408).json({
      error: 'Request timeout'
    });
  });
  next();
});

// Input validation schema
const userQuerySchema = Joi.object({
  limit: Joi.number().integer().min(1).max(100).default(10),
  offset: Joi.number().integer().min(0).default(0),
  sort: Joi.string().valid('name', 'id', 'email').default('name'),
  order: Joi.string().valid('asc', 'desc').default('asc')
});

// Enhanced health check with error handling
app.get('/health', (req, res) => {
  try {
    // Validate query parameters if present
    const { error: queryError, value: query } = userQuerySchema.validate(req.query, { abortEarly: false, allowUnknown: true });

    if (queryError) {
      return res.status(400).json({
        error: 'Invalid query parameters',
        details: queryError.details.map(detail => detail.message)
      });
    }

    const healthData = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      nodeVersion: process.version,
      memoryUsage: process.memoryUsage()
    };

    // Add query info if requested
    if (Object.keys(req.query).length > 0) {
      healthData.query = query;
    }

    res.json(healthData);
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({
      error: 'Health check failed',
      message: process.env.NODE_ENV === 'production' ? 
        'Internal server error' : error.message
    });
  }
});

// Users endpoint with input validation and error handling
app.get('/users', async (req, res) => {
  try {
    // Validate query parameters
    const { error: queryError, value: query } = userQuerySchema.validate(req.query, { abortEarly: false });

    if (queryError) {
      return res.status(400).json({
        error: 'Invalid query parameters',
        details: queryError.details.map(detail => detail.message)
      });
    }

    // Simulate database query with the validated parameters
    // In a real app, this would be a database query
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply sorting
    const sortedUsers = [...users].sort((a, b) => {
      const field = query.sort;
      const direction = query.order === 'desc' ? -1 : 1;

      if (a[field] < b[field]) return -1 * direction;
      if (a[field] > b[field]) return 1 * direction;
      return 0;
    });

    // Apply pagination
    const startIndex = query.offset;
    const paginatedUsers = sortedUsers.slice(startIndex, startIndex + query.limit);

    // Return paginated results with metadata
    res.json({
      data: paginatedUsers,
      meta: {
        total: users.length,
        limit: query.limit,
        offset: query.offset,
        pages: Math.ceil(users.length / query.limit)
      }
    });

  } catch (error) {
    console.error('Users endpoint error:', error);

    // Handle different types of errors appropriately
    if (error.name === 'ValidationError') {
      return res.status(400).json({
        error: 'Validation error',
        message: error.message
      });
    }

    res.status(500).json({
      error: 'Internal server error',
      message: process.env.NODE_ENV === 'production' ? 
        'An error occurred while processing your request' : error.message
    });
  }
});

// Handle 404 for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Route not found',
    message: `Cannot ${req.method} ${req.url}`
  });
});

// Global error handler
app.use((error, req, res, next) => {
  console.error('Unhandled error:', error);

  // Determine status code based on error
  const statusCode = error.statusCode || error.status || 500;

  res.status(statusCode).json({
    error: 'Internal server error',
    message: process.env.NODE_ENV === 'production' ? 
      'An unexpected error occurred' : error.message,
    ...(process.env.NODE_ENV !== 'production' && { stack: error.stack })
  });
});

// Graceful shutdown
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // Application specific logging, throwing an error, or other logic here
  server.close(() => {
    process.exit(1);
  });
});

process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  // Perform any necessary cleanup
  server.close(() => {
    process.exit(1);
  });
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

module.exports = { app, server };

