  next();
});

// Health check endpoint with proper error handling
app.get('/health', (req, res, next) => {
  try {
    // Simulate potential async operation that could fail
    const healthData = { 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      environment: process.env.NODE_ENV || 'development'
    };

    // Add version info if available
    if (process.env.npm_package_version) {
      healthData.version = process.env.npm_package_version;
    }

    res.status(200).json(healthData);
  } catch (error) {
    next(error);
  }
});

// Users endpoint with potential query parameter validation
app.get('/users', (req, res, next) => {
  try {
    // Input validation for query parameters
    const { limit, offset, search } = req.query;

    // Default values
    let processedLimit = 10;
    let processedOffset = 0;
    let processedSearch = '';

    // Validate and sanitize limit
    if (limit) {
      const numLimit = parseInt(limit, 10);
      if (isNaN(numLimit) || numLimit < 1 || numLimit > 100) {
        const error = new Error('Invalid limit parameter. Must be between 1 and 100.');
        error.statusCode = 400;
        throw error;
      }
      processedLimit = numLimit;
    }

    // Validate and sanitize offset
    if (offset) {
      const numOffset = parseInt(offset, 10);
      if (isNaN(numOffset) || numOffset < 0) {
        const error = new Error('Invalid offset parameter. Must be a positive number.');
        error.statusCode = 400;
        throw error;
      }
      processedOffset = numOffset;
    }

    // Sanitize search parameter
    if (search) {
      processedSearch = String(search).trim().toLowerCase();
    }

    // Mock user data
    let users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      { id: 4, name: 'Diana', email: 'diana@example.com' }
    ];

    // Filter by search if provided
    if (processedSearch) {
      users = users.filter(user => 
        user.name.toLowerCase().includes(processedSearch) ||
        user.email.toLowerCase().includes(processedSearch)
      );
    }

    // Apply pagination
    const total = users.length;
    const paginatedUsers = users.slice(processedOffset, processedOffset + processedLimit);

    // Return response with pagination metadata
    res.status(200).json({
      data: paginatedUsers,
      pagination: {
        total,
        count: paginatedUsers.length,
        offset: processedOffset,
        limit: processedLimit
      }
    });

  } catch (error) {
    next(error);
  }
});

// Handle undefined routes
app.all('*', (req, res, next) => {
  const error = new Error(`Can't find ${req.originalUrl} on this server!`);
  error.statusCode = 404;
  error.status = 'fail';
  next(error);
});

// Global error handling middleware
app.use((error, req, res, next) => {
  // Set default values
  error.statusCode = error.statusCode || 500;
  error.status = error.status || 'error';

  // Log the error (in production, you'd want to use a proper logging system)
  console.error('Error:', error);

  // Don't leak sensitive error details in production
  if (process.env.NODE_ENV === 'production') {
    // Send generic message for certain error types
    if (error.statusCode === 500) {
      res.status(error.statusCode).json({
        status: error.status,
        message: 'Something went wrong!'
      });
      return;
    }

    // Send the error message for client errors
    res.status(error.statusCode).json({
      status: error.status,
      message: error.message
    });
    return;
  }

  // In development, send detailed error
  res.status(error.statusCode).json({
    status: error.status,
    message: error.message,
    stack: error.stack,
    statusCode: error.statusCode
  });
});

// Graceful shutdown handling
const server = app.listen(process.env.PORT || 3000, () => {
  console.log(`Server running on port ${process.env.PORT || 3000}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (err) => {
  console.error('UNHANDLED REJECTION! 💥 Shutting down...');
  console.error(err);
  server.close(() => {
    process.exit(1);
  });
});

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('UNCAUGHT EXCEPTION! 💥 Shutting down...');
  console.error(err);
  process.exit(1);
});

module.exports = app;

