#!/usr/bin/env node

// Simplified credential testing script using only Node.js core modules
// This script checks connectivity to services defined in .env.test

const https = require('https');
const http = require('http');
const fs = require('fs');
const url = require('url');

// Read .env.test file
function readEnvFile() {
  try {
    const content = fs.readFileSync('.env.test', 'utf8');
    const envVars = {};

    content.split('\n').forEach(line => {
      if (line.trim() && !line.startsWith('#')) {
        const [key, value] = line.split('=');
        if (key && value) {
          envVars[key.trim()] = value.trim();
        }
      }
    });

    return envVars;
  } catch (error) {
    console.error('❌ Error reading .env.test file:', error.message);
    return null;
  }
}

// Make HTTP/HTTPS request with timeout
function makeRequest(options, postData = null) {
  return new Promise((resolve) => {
    const client = options.protocol === 'https:' ? https : http;

    const req = client.request(options, (res) => {
      let data = '';

      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        resolve({
          success: true,
          statusCode: res.statusCode,
          headers: res.headers,
          data: data
        });
      });
    });

    req.on('error', (error) => {
      resolve({
        success: false,
        error: error.message
      });
    });

    // Set timeout
    req.setTimeout(5000, () => {
      req.destroy();
      resolve({
        success: false,
        error: 'Request timeout'
      });
    });

    // Write post data if provided
    if (postData) {
      req.write(postData);
    }

    req.end();
  });
}

// Test database connectivity by attempting to connect to the host
async function testDatabase(databaseUrl) {
  console.log('\n🔍 Testing database connection...');

  if (!databaseUrl) {
    console.log('❌ DATABASE_URL not configured');
    return { success: false, error: 'DATABASE_URL not configured' };
  }

  try {
    // Parse the database URL
    const dbUrl = new url.URL(databaseUrl);
    const host = dbUrl.hostname;
    const port = dbUrl.port || (dbUrl.protocol === 'postgres:' ? 5432 : 5432);

    // Instead of using pg module, we'll check if we can connect to the host/port
    // using a simple TCP connection attempt via HTTP HEAD request to a common
    // PostgreSQL admin page (this is a basic connectivity test)

    const options = {
      hostname: host,
      port: port,
      path: '/',
      method: 'HEAD',
      timeout: 5000,
      rejectUnauthorized: false
    };

    const result = await makeRequest(options);

    if (result.success) {
      console.log('✅ Database host is reachable');
      return { success: true, message: 'Database host reachable' };
    } else {
      // Check if it's a ECONNREFUSED or similar network error
      if (result.error.includes('ECONNREFUSED') || result.error.includes('connect')) {
        console.log(`❌ Cannot connect to database host ${host}:${port}`);
        return { success: false, error: `Connection refused: ${host}:${port}` };
      } else {
        console.log(`⚠️  Database connectivity issue: ${result.error}`);
        return { success: false, error: result.error };
      }
    }

  } catch (error) {
    console.log(`❌ Database test error: ${error.message}`);
    return { success: false, error: error.message };
  }
}

// Test Anthropic API key
async function testAnthropic(apiKey) {
  console.log('\n🔍 Testing Anthropic API key...');

  if (!apiKey) {
    console.log('❌ ANTHROPIC_API_KEY not configured');
    return { success: false, error: 'ANTHROPIC_API_KEY not configured' };
  }

  const options = {
    hostname: 'api.anthropic.com',
    port: 443,
    path: '/v1/complete',
    method: 'POST',
    protocol: 'https:',
    headers: {
      'Content-Type': 'application/json',
      'x-api-key': apiKey,
      'anthropic-version': '2023-06-01'
    }
  };

  // Minimal request body
  const requestBody = JSON.stringify({
    model: "claude-2.1",
    prompt: "\n\nHuman: Hi\n\nAssistant:",
    max_tokens_to_sample: 1
  });

  const result = await makeRequest(options, requestBody);

  if (!result.success) {
    console.log(`❌ Anthropic API request failed: ${result.error}`);
    return { success: false, error: result.error };
  }

  if (result.statusCode === 401) {
    console.log('❌ Anthropic API key is invalid (401 Unauthorized)');
    return { success: false, error: 'Invalid API key' };
  } else if (result.statusCode === 429) {
    console.log('⚠️  Anthropic API rate limited (429) - key might be valid but rate limited');
    return { success: true, message: 'API key valid but rate limited' };
  } else if (result.statusCode >= 200 && result.statusCode < 300) {
    console.log(`✅ Anthropic API key is valid (status: ${result.statusCode})`);
    return { success: true, message: `API key valid (status: ${result.statusCode})` };
  } else {
    console.log(`❌ Anthropic API returned unexpected status: ${result.statusCode}`);
    return { success: false, error: `Unexpected status: ${result.statusCode}` };
  }
}

// Test Stripe API key
async function testStripe(apiKey) {
  console.log('\n🔍 Testing Stripe API key...');

  if (!apiKey) {
    console.log('❌ STRIPE_SECRET_KEY not configured');
    return { success: false, error: 'STRIPE_SECRET_KEY not configured' };
  }

  const options = {
    hostname: 'api.stripe.com',
    port: 443,
    path: '/v1/account',
    method: 'GET',
    protocol: 'https:',
    headers: {
      'Authorization': `Bearer ${apiKey}`
    }
  };

  const result = await makeRequest(options);

  if (!result.success) {
    console.log(`❌ Stripe API request failed: ${result.error}`);
    return { success: false, error: result.error };
  }

  if (result.statusCode === 200) {
    console.log('✅ Stripe API key is valid');
    return { success: true, message: 'API key valid' };
  } else if (result.statusCode === 401) {
    console.log('❌ Stripe API key is invalid (401 Unauthorized)');
    return { success: false, error: 'Invalid API key' };
  } else {
    console.log(`❌ Stripe API returned status: ${result.statusCode}`);
    return { success: false, error: `Unexpected status: ${result.statusCode}` };
  }
}

// Test AWS credentials
async function testAWS(accessKeyId, secretAccessKey) {
  console.log('\n🔍 Testing AWS credentials...');

  if (!accessKeyId || !secretAccessKey) {
    console.log('❌ AWS credentials not fully configured');
    return { success: false, error: 'AWS credentials not fully configured' };
  }

  // Test connectivity to AWS STS service
  const options = {
    hostname: 'sts.amazonaws.com',
    port: 443,
    path: '/?Action=GetCallerIdentity&Version=2011-06-15',
    method: 'POST',
    protocol: 'https:',
    headers: {
      'Content-Type': 'application/x-www-form-urlencoded',
      'Host': 'sts.amazonaws.com'
    }
  };

  // Note: In a real implementation, you'd need to sign this request with AWS Signature v4
  // This basic test will likely return 403 but still tests network connectivity
  const result = await makeRequest(options);

  if (!result.success) {
    console.log(`❌ AWS request failed: ${result.error}`);
    return { success: false, error: result.error };
  }

  // 403 is expected if credentials are invalid (which they are, as canaries)
  if (result.statusCode === 403) {
    console.log('✅ Successfully reached AWS (403 Forbidden - expected with canary credentials)');
    return { success: true, message: 'Connected to AWS (403 expected)' };
  } else if (result.statusCode === 200) {
    console.log('✅ AWS credentials are valid!');
    return { success: true, message: 'Credentials valid' };
  } else {
    console.log(`❌ AWS returned unexpected status: ${result.statusCode}`);
    return { success: false, error: `Unexpected status: ${result.statusCode}` };
  }
}

// Test Logfire token
async function testLogfire(token) {
  console.log('\n🔍 Testing Logfire token...');

  if (!token) {
    console.log('❌ LOGFIRE_TOKEN not configured');
    return { success: false, error: 'LOGFIRE_TOKEN not configured' };
  }

  const options = {
    hostname: 'api.logfire.io',
    port: 443,
    path: '/v1/health',
    method: 'GET',
    protocol: 'https:',
    headers: {
      'Authorization': `Bearer ${token}`
    }
  };

  const result = await makeRequest(options);

  if (!result.success) {
    console.log(`❌ Logfire request failed: ${result.error}`);
    return { success: false, error: result.error };
  }

  if (result.statusCode === 200) {
    console.log('✅ Logfire token is valid');
    return { success: true, message: 'Token valid' };
  } else if (result.statusCode === 401) {
    console.log('❌ Logfire token is invalid (401 Unauthorized)');
    return { success: false, error: 'Invalid token' };
  } else {
    console.log(`❌ Logfire returned status: ${result.statusCode}`);
    return { success: false, error: `Unexpected status: ${result.statusCode}` };
  }
}

// Main function
async function main() {
  console.log('🛡️  Starting credential validity tests...');
  console.log('\n⚠️  Note: This script tests connectivity and authentication only');
  console.log('   It does not access any sensitive data or make destructive changes');

  // Read environment variables
  const envVars = readEnvFile();
  if (!envVars) {
    console.error('❌ Failed to read environment variables');
    return;
  }

  // Run tests
  const results = {};

  results.database = await testDatabase(envVars.DATABASE_URL);
  results.anthropic = await testAnthropic(envVars.ANTHROPIC_API_KEY);
  results.stripe = await testStripe(envVars.STRIPE_SECRET_KEY);
  results.aws = await testAWS(envVars.AWS_ACCESS_KEY_ID, envVars.AWS_SECRET_ACCESS_KEY);
  results.logfire = await testLogfire(envVars.LOGFIRE_TOKEN);

  // Display summary
  console.log('\n📋 Test Summary:');
  console.log('-'.repeat(50));

  let reachableCount = 0;
  let totalCount = 0;

  Object.entries(results).forEach(([service, result]) => {
    if (result.success !== false) {
      console.log(`✅ ${service.toUpperCase().padEnd(12)} Reachable`);
      reachableCount++;
    } else {
      console.log(`❌ ${service.toUpperCase().padEnd(12)} Not reachable: ${result.error}`);
    }
    totalCount++;
  });

  console.log('-'.repeat(50));
  console.log(`📊 ${reachableCount}/${totalCount} services reachable\n`);

  // Return exit code based on results
  process.exit(reachableCount > 0 ? 0 : 1);
}

// Run if called directly
if (require.main === module) {
  main().catch(err => {
    console.error('❌ Script error:', err);
    process.exit(1);
  });
}

module.exports = { main, testDatabase, testAnthropic, testStripe, testAWS, testLogfire };

