const validateIdParam = (req, res, next) => {
  const id = req.params.id;

  // Basic validation for numeric ID
  if (id && (isNaN(id) || id.trim() === '')) {
    return res.status(400).json({
      error: 'Invalid ID format. ID must be a number.'
    });
  }

  // Prevent prototype pollution attempts
  if (id === '__proto__' || id === 'constructor' || id === 'prototype') {
    return res.status(400).json({
      error: 'Invalid parameter value'
    });
  }

  next();
};

// Rate limiting using a simple in-memory store
const requestCounts = new Map();
const RATE_LIMIT_WINDOW = 15 * 60 * 1000; // 15 minutes
const RATE_LIMIT_MAX = 100; // Max requests per window

app.use((req, res, next) => {
  // Skip rate limiting for health checks
  if (req.path === '/health') {
    return next();
  }

  const clientIP = req.ip || 'unknown';
  const now = Date.now();

  // Clean up old entries
  if (requestCounts.size > 1000) {
    // Simple cleanup if we have too many entries
    const cutoff = now - RATE_LIMIT_WINDOW;
    for (const [key, value] of requestCounts) {
      if (value.timestamp < cutoff) {
        requestCounts.delete(key);
      }
    }
  }

  // Get or create counter for this IP
  let counter = requestCounts.get(clientIP) || { count: 0, timestamp: now };

  // Reset counter if outside the window
  if (now - counter.timestamp > RATE_LIMIT_WINDOW) {
    counter = { count: 1, timestamp: now };
    requestCounts.set(clientIP, counter);
    return next();
  }

  // Check if limit exceeded
  if (counter.count >= RATE_LIMIT_MAX) {
    return res.status(429).json({
      error: 'Too many requests from this IP, please try again later.'
    });
  }

  // Increment counter
  counter.count++;
  requestCounts.set(clientIP, counter);
  next();
});

