    let responseUsers = mockUsers;
    if (req.query.page && req.query.limit) {
      const page = parseInt(req.query.page);
      const limit = parseInt(req.query.limit);
      const startIndex = (page - 1) * limit;
      responseUsers = mockUsers.slice(startIndex, startIndex + limit);
    }

    // Never expose sensitive data like passwords, API keys, etc.
    res.json({
      data: responseUsers,
      total: mockUsers.length,
      page: req.query.page ? parseInt(req.query.page) : 1,
      limit: req.query.limit ? parseInt(req.query.limit) : mockUsers.length
    });

  } catch (error) {
    // Log the error (in production, use a proper logging service)
