/**
 * Input validation and sanitization middleware
 */
const validator = require('validator');

/**
 * Sanitize and validate user input
 * @param {Object} input - The input object to sanitize
 * @returns {Object} Sanitized input
 */
const sanitizeInput = (input) => {
  if (!input || typeof input !== 'object') return {};

  const sanitized = {};

  for (let [key, value] of Object.entries(input)) {
    // Skip prototype properties
    if (key === '__proto__' || key === 'constructor' || key === 'prototype') {
      continue;
    }

    if (typeof value === 'string') {
      // Basic XSS prevention - strip potentially dangerous HTML
      sanitized[key] = validator.escape(value.trim());
    } else {
      sanitized[key] = value;
    }
  }

  return sanitized;
};

/**
 * Validate email format
 * @param {string} email - Email to validate
 * @returns {boolean} Whether email is valid
 */
const isValidEmail = (email) => {
  if (!email) return false;
  return validator.isEmail(email);
};

/**
 * Validate that input doesn't contain malicious patterns
 * @param {Object} input - Input to validate
 * @returns {Object} { isValid: boolean, errors: string[] }
 */
const validateInputSecurity = (input) => {
  const errors = [];

  if (!input || typeof input !== 'object') {
    errors.push('Invalid input type');
    return { isValid: false, errors };
  }

  for (let [key, value] of Object.entries(input)) {
    // Block prototype pollution attempts
    if (key === '__proto__' || key === 'constructor' || key === 'prototype') {
      errors.push(`Malicious property detected: ${key}`);
      continue;
    }

    if (typeof value === 'string') {
      // Block common XSS patterns
      if (/<script/i.test(value)) {
        errors.push(`XSS attempt detected in field: ${key}`);
      }

      // Block SQL injection patterns
      const sqlPatterns = [/ union\s+select\b/i, /\bor\s+1=1\b/i, /\bexec(ute)?\b/i, /\bdrop\b/i, /\binsert\b/i];
      if (sqlPatterns.some(pattern => pattern.test(value))) {
        errors.push(`SQL injection attempt detected in field: ${key}`);
      }
    }
  }

  return {
    isValid: errors.length === 0,
    errors
  };
};

module.exports = {
  sanitizeInput,
  isValidEmail,
  validateInputSecurity
};

/**
 * Centralized error handling middleware
 */

/**
 * Handle application errors
 * @param {Error} error - The error object
 * @param {Object} req - Express request object
 * @param {Object} res - Express response object
 * @param {Function} next - Next middleware function
 */
const errorHandler = (error, req, res, next) => {
