{
  "name": "secure-express-app",
  "version": "1.0.0",
  "description": "A secure Express application with proper error handling and input validation",
  "main": "app.js",
  "scripts": {
    "start": "node app.js",
    "dev": "nodemon app.js"
  },
  "dependencies": {
    "express": "^4.18.0",
    "helmet": "^7.0.0",
    "express-rate-limit": "^6.8.1",
    "express-validator": "^7.0.1"
  },
  "devDependencies": {
    "nodemon": "^3.0.1"
  },
  "keywords": ["express", "security", "validation"],
  "author": "",
  "license": "MIT"
}

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');

const app = express();

// Security middleware
app.use(helmet({
  contentSecurityPolicy: false, // Disable CSP for now, configure separately
  crossOriginEmbedderPolicy: false // Required for some localhost development
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  standardHeaders: true, // Return rate limit info in the RateLimit-* headers
  legacyHeaders: false, // Disable the X-RateLimit-* headers
  message: {
    error: 'Too many requests from this IP, please try again later.'
  }
});

// Apply rate limit to all requests
app.use(limiter);

// Parse JSON bodies
app.use(express.json({
  limit: '10kb' // Limit request body size
}));

// Health check endpoint with input validation
app.get('/health', [
  // Validate query parameters
  query('detailed').optional().isBoolean().withMessage('Detailed must be a boolean'),
  query('format').optional().isIn(['json', 'text']).withMessage('Format must be json or text')
], (req, res) => {
  // Check for validation errors
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array()
    });
  }

  const healthData = {
    status: 'ok',
    timestamp: new Date().toISOString(),
    version: '1.0.0'
  };

  // Add detailed info if requested
  if (req.query.detailed === 'true') {
    healthData.environment = process.env.NODE_ENV || 'unknown';
  }

  // Return different formats if requested
  if (req.query.format === 'text') {
    return res.type('text').send(`Status: ${healthData.status}, Timestamp: ${healthData.timestamp}`);
  }

  res.json(healthData);
});

// Users endpoint with improved security
app.get('/users', [
  // Validate pagination parameters
  query('page').optional().isInt({ min: 1 }).withMessage('Page must be a positive integer'),
  query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
  query('sort').optional().isIn(['name', 'id', '-name', '-id']).withMessage('Sort must be name, id, -name, or -id')
], (req, res) => {
  // Check for validation errors
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array()
    });
  }

  // Simulated users data
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // In a real application, we would filter, paginate and sort the data based on query parameters
  // For now, we'll just return the data with metadata
  const response = {
    data: users,
    total: users.length,
    page: parseInt(req.query.page) || 1,
    totalPages: 1
  };

  res.json(response);
});

// Catch 404 for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Route not found',
    path: req.path
  });
});

// Global error handling middleware
app.use((err, req, res, next) => {
  console.error('Internal server error:', err);

  // Handle specific error types
  if (err.name === 'ValidationError') {
    return res.status(400).json({
      error: 'Validation error',
      message: err.message
    });
  }

  // Handle JSON parsing errors
  if (err instanceof SyntaxError && err.status === 400 && 'body' in err) {
    return res.status(400).json({
      error: 'Invalid JSON in request body'
    });
  }

  // Default to generic error message
  res.status(500).json({
    error: 'Internal server error',
    message: 'An unexpected error occurred'
  });
});

// Graceful error handling for server startup
const PORT = process.env.PORT || 3000;
let server;

try {
  server = app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
    console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
  });

  // Handle graceful shutdown
  process.on('SIGTERM', () => {
    console.log('SIGTERM received, shutting down gracefully');
    server.close(() => {
      console.log('Process terminated');
    });
  });

  process.on('SIGINT', () => {
    console.log('SIGINT received, shutting down gracefully');
    server.close(() => {
      console.log('Process terminated');
    });
  });
} catch (error) {
  console.error('Failed to start server:', error);
  process.exit(1);
}

module.exports = app;

