const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const xss = require('xss-clean');
const logger = require('./logger'); // Assuming a logger module exists

const app = express();

// Security middleware
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"]
    }
  }
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});

// Apply rate limiter to all requests
app.use(limiter);

// Data sanitization against XSS
app.use(xss());

// Middleware to parse JSON with size limit
app.use(express.json({
  limit: '10kb'
}));

// Custom error class
class AppError extends Error {
  constructor(message, statusCode) {
    super(message);
    this.statusCode = statusCode;
    this.status = `${statusCode}`.startsWith('4') ? 'fail' : 'error';
    this.isOperational = true;

    Error.captureStackTrace(this, this.constructor);
  }
}

// Health check endpoint with error handling
app.get('/health', (req, res, next) => {
  try {
    // Validate query parameters if any
    const allowedParams = ['verbose', 'format'];
    const invalidParams = Object.keys(req.query).filter(
      param => !allowedParams.includes(param)
    );

    if (invalidParams.length > 0) {
      return next(new AppError(`Invalid query parameters: ${invalidParams.join(', ')}`, 400));
    }

    // Validate parameter values
    if (req.query.verbose && !['true', 'false'].includes(req.query.verbose)) {
      return next(new AppError('Invalid value for verbose parameter', 400));
    }

    const response = {
      status: 'ok', 
      timestamp: new Date().toISOString()
    };

    // Add verbose information if requested
    if (req.query.verbose === 'true') {
      response.environment = process.env.NODE_ENV || 'development';
    }

    res.json(response);
  } catch (err) {
    logger.error('Health check error:', err);
    next(new AppError('Internal server error', 500));
  }
});

// Users endpoint with input validation
app.get('/users', (req, res, next) => {
  try {
    // Input validation
    let page = 1;
    let limit = 10;

    if (req.query.page) {
      page = parseInt(req.query.page, 10);
      if (isNaN(page) || page < 1) {
        return next(new AppError('Page must be a positive integer', 400));
      }
    }

    if (req.query.limit) {
      limit = parseInt(req.query.limit, 10);
      if (isNaN(limit) || limit < 1 || limit > 100) {
        return next(new AppError('Limit must be a positive integer between 1 and 100', 400));
      }
    }

    // Simulated user data (in a real app, this would come from a database)
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Simple pagination
    const startIndex = (page - 1) * limit;
    const endIndex = page * limit;
    const paginatedUsers = users.slice(startIndex, endIndex);

    res.json({
      status: 'success',
      data: {
        users: paginatedUsers
      },
      pagination: {
        currentPage: page,
        totalPages: Math.ceil(users.length / limit),
        totalUsers: users.length,
        hasNext: endIndex < users.length,
        hasPrev: startIndex > 0
      }
