        path: '/health', // Common health check endpoint
        method: 'GET',
        timeout: 5000, // 5 second timeout
        // Importantly: no authentication headers or credentials sent
      };

      const reqProtocol = protocol === 'https' ? https : http;

      const req = reqProtocol.request(options, (res) => {
        this.results[`${host}_reachability`] = {
          reachable: true,
          statusCode: res.statusCode,
          message: `Host responded with status ${res.statusCode}`
        };

        // Consume response data to prevent memory leak
        res.on('data', () => {});
        resolve();
