const express = require('express');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');

const app = express();

// Security middleware
app.use(helmet()); // Security headers
app.use(helmet.hidePoweredBy()); // Hide Express server signature

// Prevent XSS attacks
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  next();
});

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per window
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the RateLimit-* headers
  legacyHeaders: false, // Disable the X-RateLimit-* headers
});

// Apply rate limiter to all requests
app.use(limiter);

// CORS configuration
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || false, // Only allow specific origins in production
  optionsSuccessStatus: 200,
}));

// Body parsing with size limits
app.use(express.json({
  limit: '10kb', // Limit request body size
  strict: true, // Only accept valid JSON
}));

app.use(express.urlencoded({
  extended: true,
  limit: '10kb',
}));

// Input validation middleware
const validateQueryParam = (paramName, allowedValues = null) => {
  return (req, res, next) => {
    const value = req.query[paramName];

    if (value !== undefined) {
      // Input sanitization
      const sanitizedValue = String(value).trim();

      // Validate against allowed values if provided
      if (allowedValues && !allowedValues.includes(sanitizedValue)) {
        return res.status(400).json({
          error: `Invalid value for ${paramName}. Allowed values: ${allowedValues.join(', ')}`
        });
      }

      // Store sanitized value back in req.query
      req.query[paramName] = sanitizedValue;
    }

    next();
  };
};

// Health check with error handling
app.get('/health', 
  validateQueryParam('format', ['json', 'text']),
  (req, res) => {
    try {
      const timestamp = new Date().toISOString();

      if (req.query.format === 'text') {
        res.type('text');
        res.send(`status: ok\ntimestamp: ${timestamp}`);
      } else {
        res.json({ 
          status: 'ok', 
          timestamp: timestamp,
          uptime: process.uptime()
        });
      }
    } catch (error) {
      console.error('Health check error:', error);
      res.status(500).json({ 
        error: 'Health check failed',
        message: process.env.NODE_ENV === 'production' ? 
          'Internal server error' : error.message 
      });
    }
  }
);

// Users endpoint with proper error handling
app.get('/users', (req, res) => {
  try {
    // Simulated users data
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Simple query parameter filtering
    const search = req.query.search;
    if (search) {
      const searchTerm = String(search).toLowerCase().trim();
      const filteredUsers = users.filter(user => 
        user.name.toLowerCase().includes(searchTerm) ||
        user.email.toLowerCase().includes(searchTerm)
      );
      res.json(filteredUsers);
    } else {
      res.json(users);
    }
  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({ 
      error: 'Failed to retrieve users',
      message: process.env.NODE_ENV === 'production' ? 
        'Internal server error' : error.message 
    });
  }
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Route not found',
    path: req.path
  });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error('Uncaught error:', err);

  // Handle specific error types
  if (err.name === 'SyntaxError' && err.status === 400 && 'body' in err) {
    return res.status(400).json({
      error: 'Invalid JSON in request body'
    });
  }

  res.status(500).json({ 
    error: 'Internal server error',
    message: process.env.NODE_ENV === 'production' ? 
      'Internal server error' : err.message 
  });
});

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || 'localhost';

app.listen(PORT, HOST, () => {
  console.log(`Server running on http://${HOST}:${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

module.exports = app;

