const express = require('express');
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');
const cors = require('cors');
const sanitize = require('sanitize'); // For input sanitization

const app = express();

// Security middleware
app.use(helmet()); // Set security HTTP headers
app.use(helmet.hidePoweredBy()); // Hide Express version

// CORS configuration - restrict to trusted domains in production
app.use(cors({
  origin: process.env.NODE_ENV === 'production' 
    ? ['https://trusted-domain.com'] 
    : true // Allow all in development
}));

// Rate limiting to prevent DDoS
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the RateLimit-* headers
  legacyHeaders: false, // Disable the X-RateLimit-* headers
});

// Apply rate limit to all requests
app.use(limiter);

// Body parsing with size limits to prevent DOS
app.use(express.json({
  limit: '10kb' // Limit request body size
}));

app.use(express.urlencoded({ 
  extended: true, 
  limit: '10kb' 
}));

// Input sanitization middleware
app.use((req, res, next) => {
  // Sanitize query parameters
  if (req.query) {
    Object.keys(req.query).forEach(key => {
      if (typeof req.query[key] === 'string') {
        req.query[key] = sanitize.html(req.query[key]);
      }
    });
  }
  // Sanitize body parameters
  if (req.body) {
    Object.keys(req.body).forEach(key => {
      if (typeof req.body[key] === 'string') {
        req.body[key] = sanitize.html(req.body[key]);
      }
    });
  }
  next();
});

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    // Validate query parameters if any
    const { detailed } = req.query;

    // Input validation
    if (detailed !== undefined && detailed !== 'true' && detailed !== 'false') {
      return res.status(400).json({
        error: 'Invalid parameter: detailed must be "true" or "false"'
      });
    }

    const response = { 
      status: 'ok', 
      timestamp: new Date().toISOString() 
    };

    // Add detailed info if requested
    if (detailed === 'true') {
      response.environment = process.env.NODE_ENV;
      response.uptime = process.uptime();
    }

    res.json(response);
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Users endpoint
app.get('/users', (req, res) => {
  try {
    // Validate query parameters for pagination/filtering
    let { limit, offset, name } = req.query;

    // Input validation and sanitization
    const parsedLimit = limit ? parseInt(limit, 10) : 10;
    const parsedOffset = offset ? parseInt(offset, 10) : 0;

    // Validate and sanitize inputs
    if (isNaN(parsedLimit) || parsedLimit < 1 || parsedLimit > 100) {
      return res.status(400).json({
        error: 'Invalid limit parameter: must be between 1 and 100'
      });
    }

    if (isNaN(parsedOffset) || parsedOffset < 0) {
      return res.status(400).json({
        error: 'Invalid offset parameter: must be a non-negative integer'
      });
    }

    // Sanitize name parameter if provided
    const sanitizedName = name ? name.trim() : null;

    if (sanitizedName && sanitizedName.length > 100) {
      return res.status(400).json({
        error: 'Name parameter too long'
      });
    }

    // Mock user data
    let users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Filter by name if provided
    if (sanitizedName) {
      users = users.filter(user => 
        user.name.toLowerCase().includes(sanitizedName.toLowerCase())
      );
    }

    // Apply pagination
    const paginatedUsers = users.slice(parsedOffset, parsedOffset + parsedLimit);

    // Return response with metadata
    res.json({
      data: paginatedUsers,
      meta: {
        total: users.length,
        limit: parsedLimit,
        offset: parsedOffset,
        hasNext: parsedOffset + parsedLimit < users.length
      }
    });

  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Route not found'
  });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error('Uncaught error:', err);

  // Hide detailed error messages in production
  const isProduction = process.env.NODE_ENV === 'production';

  res.status(err.status || 500).json({
    error: isProduction 
      ? 'Internal server error' 
      : err.message || 'Internal server error',
    // Include stack only in development
    ...(isProduction ? {} : { stack: err.stack })
  });
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (err) => {
  console.error('Unhandled Promise Rejection:', err);
  server.close(() => process.exit(1));
});

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  server.close(() => process.exit(1));
});

module.exports = app;

