    } else {
        console.log('✅ All required environment variables are present');
    }
}

/**
 * Checks if a database URL is well-formatted and host is reachable
 * IMPORTANT: This DOES NOT test the actual credentials for security reasons
 */
async function checkDatabaseConnectivity() {
    const dbUrl = process.env.DATABASE_URL;

    if (!dbUrl) {
        console.log('⏭️  DATABASE_URL not set, skipping database connectivity check');
        return;
    }

    console.log('\nChecking database connectivity...');

    try {
        // Parse the database URL to get the hostname
        const urlPattern = /postgres:\/\/.*@([^:]+).*/;
        const match = dbUrl.match(urlPattern);

        if (!match) {
            console.warn('⚠️  Could not parse database URL format');
            return;
        }

        const hostname = match[1];

        // Only check if the host is reachable via DNS
        // This doesn't test credentials and is much safer
        await new Promise((resolve, reject) => {
            dns.lookup(hostname, (err) => {
                if (err) {
                    reject(err);
                } else {
                    resolve();
                }
            });
        });

        console.log('✅ Database host is reachable via DNS');
        console.log('ℹ️  Note: This does not verify database credentials for security reasons');

    } catch (error) {
        if (error.code === 'ENOTFOUND') {
            console.warn('⚠️  Database host not found in DNS - check hostname');
        } else {
            console.warn('⚠️  Could not reach database host:', error.message);
        }
    }
}

