        const urlPattern = /postgres:\/\/.*@([^:/]+).*/;
        const match = dbUrl.match(urlPattern);

        if (!match) {
            console.warn('⚠️  Could not parse database URL format');
            return;
        }

        const hostname = match[1];

        // Check if the host is reachable via DNS
        // This doesn't test credentials and is much safer
        await new Promise((resolve, reject) => {
            dns.lookup(hostname, (err) => {
                if (err) {
                    reject(err);
                } else {
                    resolve();
                }
            });
        });

        console.log(`✅ Database host '${hostname}' is reachable via DNS`);
        console.log('ℹ️  Note: This does not verify database credentials for security reasons');

    } catch (error) {
        if (error.code === 'ENOTFOUND') {
            console.warn(`⚠️  Database host not found in DNS - check hostname: ${error.hostname}`);
        } else {
            console.warn(`⚠️  Could not reach database host: ${error.message}`);
        }
    }
}

/**
 * Validates API keys by checking their format
 * Note: This doesn't make actual API calls to validate keys
 */
function validateApiKeys() {
    console.log('\nValidating API key formats...');

    // API key patterns
    const keyPatterns = {
        'AWS Access Key': { 
            var: 'AWS_ACCESS_KEY_ID', 
            pattern: /^AKIA[0-9A-Z]{16}$/,
            example: 'AKIA01234567890ABCDEF'
        },
        'Stripe Secret Key': { 
            var: 'STRIPE_SECRET_KEY', 
            pattern: /^sk_(test|live)_[a-zA-Z0-9]{12,}$/,
            example: 'sk_test_123456789 or sk_live_123456789'
        },
        'Anthropic API Key': { 
            var: 'ANTHROPIC_API_KEY', 
            pattern: /^sk-ant-[a-zA-Z0-9-]{20,}$/, 
            example: 'sk-ant-api-key-1a2b3c4d5e'
        }
    };

    for (const [name, config] of Object.entries(keyPatterns)) {
        const key = process.env[config.var];

        if (!key) {
            console.log(`⏭️  ${config.var} not set, skipping validation`);
            continue;
        }

        // Check if the key matches the expected pattern
        if (config.pattern.test(key)) {
            console.log(`✅ ${name}: format valid`);

            // Additional warnings based on key type
            if (name === 'Stripe Secret Key' && key.includes('sk_live')) {
                console.log('   ⚠️  This appears to be a live Stripe key - handle with extreme care!');
            }

            // Check for canary/test indicators
            if (key.toLowerCase().includes('canary') || key.toLowerCase().includes('test')) {
                console.log(`   💡 This appears to be a test/canary key`);
            }
        } else {
            console.warn(`⚠️  ${name}: format invalid`);
            console.warn(`   Expected pattern like: ${config.example}`);
            console.warn(`   Your value starts with: ${key.substring(0, 20)}${key.length > 20 ? '...' : ''}`);
        }
    }

    console.log('\nℹ️  Note: Format validation does not confirm key functionality');
    console.log('    For security, actual API connectivity tests require proper environment setup');
}

/**
 * Loads environment variables from .env.test file
 */
function loadEnvTest() {
    const fs = require('fs');
    const path = require('path');

    try {
        const envTestPath = path.join(__dirname, '..', '.env.test');
        const content = fs.readFileSync(envTestPath, 'utf8');

        // Parse the .env.test file
        content.split('\n').forEach(line => {
            if (line.trim() && !line.startsWith('#')) {
                const [key, value] = line.split('=');
                if (key && value) {
                    // Only set if not already set in process.env
                    if (!process.env[key]) {
                        process.env[key] = value;
                    }
                }
            }
        });

        console.log('✅ Loaded environment variables from .env.test');
    } catch (error) {
        if (error.code === 'ENOENT') {
            console.warn('⏭️  .env.test file not found');
        } else {
            console.warn('⚠️  Error reading .env.test file:', error.message);
        }
    }
}

// Main execution
async function main() {
    console.log('🔐 Environment Validation Script');
    console.log('===============================\n');

    // Load environment variables from .env.test
    loadEnvTest();

    // Run validation checks
    validateEnvVariables();
    await checkDatabaseConnectivity();
    validateApiKeys();

    console.log('\n✅ Validation complete');
    console.log('💡 This script validates format and DNS connectivity only');
    console.log('   For security, actual credential testing requires isolated environments');
}

// Run the script
main().catch(console.error);

