const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');

const app = express();

// Security middleware
app.use(helmet({
  contentSecurityPolicy: false, // You may want to configure this based on your needs
  crossOriginEmbedderPolicy: false,
}));

// Rate limiting to prevent abuse
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.',
    statusCode: 429
  },
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(limiter);

// Enhanced health endpoint with input validation
app.get('/health', 
  // Validate query parameters if any
  query('detailed').optional().isBoolean().withMessage('Detailed must be a boolean'),
  (req, res) => {
    // Check for validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ 
        error: 'Validation failed', 
        details: errors.array(),
        statusCode: 400 
      });
    }

    try {
      const healthData = {
        status: 'ok', 
        timestamp: new Date().toISOString()
      };

      // Add detailed info if requested (and validated)
      if (req.query.detailed === 'true') {
        healthData.service = 'user-service';
        healthData.version = '1.0.0';
      }

      res.json(healthData);
    } catch (error) {
      console.error('Health check error:', error);
      res.status(500).json({ 
        error: 'Internal server error',
        statusCode: 500 
      });
    }
  }
);

// Users endpoint with validation and error handling
app.get('/users', 
  // Add validation for potential query parameters
  query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
  query('page').optional().isInt({ min: 1 }).withMessage('Page must be a positive integer'),
  (req, res) => {
    try {
      // Validate inputs
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({ 
          error: 'Validation failed', 
          details: errors.array(),
          statusCode: 400 
        });
      }

      // Get validated query parameters
      const limit = req.query.limit ? parseInt(req.query.limit) : 10;
      const page = req.query.page ? parseInt(req.query.page) : 1;

      // In a real application, this would query a database with pagination
      const mockUsers = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Apply basic filtering (in real app, this would be done at database level)
      const paginatedUsers = mockUsers.slice(0, limit);

      // Return structured response with metadata
      res.json({
        data: paginatedUsers,
        pagination: {
          page,
          limit,
          total: mockUsers.length,
          pages: Math.ceil(mockUsers.length / limit)
        }
      });

    } catch (error) {
      console.error('Users endpoint error:', error);
      res.status(500).json({ 
        error: 'Internal server error',
        statusCode: 500 
      });
    }
  }
);

// Global error handling middleware
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Prevent stack trace exposure in production
  const isProduction = process.env.NODE_ENV === 'production';

  res.status(err.statusCode || 500).json({
    error: isProduction ? 'Internal server error' : err.message,
    statusCode: err.statusCode || 500,
    ...(isProduction ? {} : { stack: err.stack }) // Only include stack in non-production
  });
});

// Handle 404 for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Route not found',
    statusCode: 404
  });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);

  // Additional security notice in console
  if (process.env.NODE_ENV !== 'production') {
    console.log('Running in development mode - ensure proper security in production');
  }
});

module.exports = app;

