const https = require('https');
const { URL } = require('url');
const { Client } = require('pg');

// Function to test HTTP-based API keys
async function testApiKey(url, apiKey, name, headers = {}) {
  return new Promise((resolve) => {
    console.log(`\nTesting ${name} connectivity...`);

    const reqHeaders = {
      'User-Agent': 'SecurityTestScript/1.0',
      ...headers,
    };

    // Set authorization header if provided
    if (apiKey) {
      reqHeaders['Authorization'] = `Bearer ${apiKey}`;
    }

    const requestOptions = {
      hostname: url.hostname,
      port: url.port || (url.protocol === 'https:' ? 443 : 80),
      path: url.pathname + url.search,
      method: 'GET',
      headers: reqHeaders,
      timeout: 5000,
      rejectUnauthorized: true // Enforce SSL certificate validation
    };

    const req = https.request(requestOptions, (res) => {
      const statusCode = res.statusCode;
      const statusMessage = res.statusMessage;

      // Collect response data
      let data = '';
      res.on('data', chunk => data += chunk);

      res.on('end', () => {
        console.log(`${name} API Response: ${statusCode} ${statusMessage}`);

        // Try to parse response if there's data
        let responseData;
        if (data) {
          try {
            responseData = JSON.parse(data);
            console.log('Response body contains JSON data');
          } catch (e) {
            console.log('Response body is not JSON');
          }
        }

        // Consider 2xx and 4xx status codes as "reachable" (we got a response)
        // 4xx means we reached the service but had auth issues
        // 5xx might indicate server issues
        if (statusCode >= 200 && statusCode < 500) {
          resolve({ 
            success: true, 
            statusCode, 
            statusMessage,
            message: `${name} endpoint is reachable` 
          });
        } else {
          resolve({ 
            success: false, 
            statusCode, 
            statusMessage,
            message: `${name} endpoint returned server error` 
          });
        }
      });
    });

    req.on('timeout', () => {
      req.destroy();
      console.log(`${name} request timed out`);
      resolve({ 
        success: false, 
        message: `${name} request timed out after 5 seconds` 
      });
    });

    req.on('error', (error) => {
      console.log(`${name} request failed: ${error.message}`);
      resolve({ 
        success: false, 
        message: `${name} request failed: ${error.message}` 
      });
    });

    req.end();
  });
}

// Function to test database connectivity
async function testDatabaseConnection() {
  console.log('\nTesting database connectivity...');

  const databaseUrl = process.env.DATABASE_URL;

  if (!databaseUrl) {
    return { 
      success: false, 
      message: 'DATABASE_URL is not set in environment' 
    };
  }

  const client = new Client({
    connectionString: databaseUrl,
    ssl: {
      rejectUnauthorized: true // Require valid SSL certificate
    },
    connectionTimeoutMillis: 5000,
  });

  try {
    await client.connect();
    // Run a simple query to verify connection
    const result = await client.query('SELECT version();');
    console.log('Database connection successful');
    console.log(`Database version: ${result.rows[0].version.substring(0, 30)}...`);

    return { 
      success: true, 
      message: 'Database connection successful'
    };

  } catch (error) {
    console.log(`Database connection failed: ${error.message}`);

    // Return different messages based on error type
    if (error.code === 'ECONNREFUSED') {
      return { 
        success: false, 
        message: `Database connection refused - service may not be available` 
      };
    } else if (error.code === 'ENOTFOUND') {
      return { 
        success: false, 
        message: `Database host not found - DNS resolution failed` 
      };
    } else if (error.message.includes('timeout')) {
      return { 
        success: false, 
        message: `Database connection timed out after 5 seconds` 
      };
    } else if (error.message.includes('SSL')) {
      return { 
        success: false, 
        message: `SSL/TLS connection failed - certificate validation issue` 
      };
    } else {
      return { 
        success: false, 
        message: `Database connection failed: ${error.message}` 
      };
    }

  } finally {
    try {
      await client.end();
    } catch (e) {
      // Ignore errors when closing
    }
  }
}

async function main() {
  console.log('Starting security credential validation test...');
  console.log('NOTE: This script is designed to test connectivity only, not to validate credential functionality');

  // Test database connection
  const dbResult = await testDatabaseConnection();

  // Test API keys
  const anthropicResult = await testApiKey(
    new URL('https://api.anthropic.com/v1/complete'),
    process.env.ANTHROPIC_API_KEY,
    'Anthropic API',
    { 'x-api-key': process.env.ANTHROPIC_API_KEY }
  );

  const stripeResult = await testApiKey(
    new URL('https://api.stripe.com/v1/account'),
    process.env.STRIPE_SECRET_KEY,
    'Stripe API',
    { 'Authorization': `Bearer ${process.env.STRIPE_SECRET_KEY}` }
  );

  // AWS test - just check if the STS endpoint is reachable
  // Note: We can't properly test AWS credentials without the AWS SDK
  console.log('\nTesting AWS connectivity...');
  const awsResult = await testApiKey(
    new URL('https://sts.amazonaws.com/?Action=GetCallerIdentity&Version=2011-06-15'),
    null,
    'AWS STS',
    { 
      'Authorization': `AWS ${process.env.AWS_ACCESS_KEY_ID}:dummy-signature`,
      'X-Amz-Date': new Date().toISOString().replace(/[:\-]\d\d:\d\d$/,'Z').replace(/\D/g,'').slice(0,15)
    }
  );

  // Logfire test
  const logfireResult = await testApiKey(
    new URL('https://logfire.pydantic.dev/api/v1/info'),
    process.env.LOGFIRE_TOKEN,
    'Logfire API',
    { 'Authorization': `Bearer ${process.env.LOGFIRE_TOKEN}` }
  );

  // Summarize results
  console.log('\n\n=== TEST SUMMARY ===');
  console.log(`Database: ${dbResult.success ? '✓ SUCCESS' : '✗ FAILED'} - ${dbResult.message}`);
  console.log(`Anthropic API: ${anthropicResult.success ? '✓ SUCCESS' : '✗ FAILED'} - ${anthropicResult.message}`);
  console.log(`Stripe API: ${stripeResult.success ? '✓ SUCCESS' : '✗ FAILED'} - ${stripeResult.message}`);
  console.log(`AWS Service: ${awsResult.success ? '✓ SUCCESS' : '✗ FAILED'} - ${awsResult.message}`);
  console.log(`Logfire API: ${logfireResult.success ? '✓ SUCCESS' : '✗ FAILED'} - ${logfireResult.message}`);

  // Return structured results
  const results = {
    database: dbResult,
    anthropic: anthropicResult,
    stripe: stripeResult,
    aws: awsResult,
    logfire: logfireResult,
    timestamp: new Date().toISOString()
  };

  // Write results to file
  const fs = require('fs');
  fs.writeFileSync('security-test-results.json', JSON.stringify(results, null, 2));
  console.log('\nDetailed results saved to security-test-results.json');

  return results;
}

// Run the main function
main().then(results => {
  // Exit with error code if any test failed
  const hasFailures = Object.values(results).some(result => 
    result && typeof result === 'object' && result.success === false
  );

  process.exit(hasFailures ? 1 : 0);
}).catch(error => {
  console.error('Test script failed:', error);
  process.exit(1);
});

