#!/usr/bin/env node
"use strict";

// Load environment variables using built-in fs module instead of dotenv
const fs = require('fs');
const https = require('https');
const { URL } = require('url');

// Read and parse .env.test file manually
function loadEnvFile() {
  try {
    const content = fs.readFileSync('.env.test', 'utf8');
    const env = {};

    content.split(/\r?\n/).forEach(line => {
      // Skip empty lines and comments
      if (line.trim() && !line.startsWith('#')) {
        const [key, value] = line.split('=');
        if (key && value) {
          env[key.trim()] = value.trim();
        }
      }
    });

    return env;
  } catch (error) {
    console.error('Failed to read .env.test file:', error.message);
    return null;
  }
}

const env = loadEnvFile();

if (!env) {
  console.error('Cannot continue without environment variables');
  process.exit(1);
}

// Function to test connectivity to a URL
function testConnectivity(name, url, headers = {}) {
  return new Promise((resolve) => {
    console.log(`\nTesting ${name} connectivity...`);

    const requestOptions = {
      hostname: url.hostname,
      port: url.port || (url.protocol === 'https:' ? 443 : 80),
      path: url.pathname + url.search,
      method: 'GET',
      headers: {
        'User-Agent': 'SecurityTestScript/1.0',
        ...headers
      },
      timeout: 5000
    };

    const req = https.request(requestOptions, (res) => {
      const statusCode = res.statusCode;
      const statusMessage = res.statusMessage;

      console.log(`${name} Response: ${statusCode} ${statusMessage}`);

      // Collect response data to avoid socket hang up
      let data = '';
      res.on('data', chunk => data += chunk);

      res.on('end', () => {
        // Consider any response (2xx, 4xx, 5xx) as proof of connectivity
        resolve({
          success: true,
          statusCode,
          statusMessage,
          message: `${name} endpoint is reachable`
        });
      });
    });

    req.on('timeout', () => {
      req.destroy();
      console.log(`${name} request timed out`);
      resolve({
        success: false,
        message: `${name} request timed out after 5 seconds`
      });
    });

    req.on('error', (error) => {
      console.log(`${name} request failed: ${error.message}`);
      resolve({
        success: false,
        message: `${name} request failed: ${error.message}`
      });
    });

    req.end();
  });
}

async function main() {
  console.log('Starting basic security credential connectivity test...');
  console.log('Note: This script only tests network connectivity, not credential validity');
  console.log(`Found ${Object.keys(env).length} environment variables\n`);

  // Test database connectivity by parsing the DATABASE_URL
  console.log('\nTesting database connectivity...');
  const dbUrl = env.DATABASE_URL;

  if (!dbUrl) {
    console.log('DATABASE_URL not found in environment');
  } else {
    console.log('Database URL found, but cannot test PostgreSQL connectivity without pg module');
    try {
      // Extract host and port from database URL
      const dbMatch = dbUrl.match(/@([^:/]+)(?::(\d+))?/);
      if (dbMatch) {
        const host = dbMatch[1];
        const port = dbMatch[2] || '5432';
        console.log(`Database host: ${host}:${port}`);
        console.log('WARNING: Cannot validate database connectivity without pg module');
      }
    } catch (e) {
      console.log('Could not parse database URL');
    }
  }

  // Test API endpoints
  const anthropicResult = await testConnectivity(
    'Anthropic API',
    new URL('https://api.anthropic.com/'),
    { 'Authorization': `Bearer ${env.ANTHROPIC_API_KEY || ''}` }
  );

  const stripeResult = await testConnectivity(
    'Stripe API',
    new URL('https://api.stripe.com/'),
    { 'Authorization': `Bearer ${env.STRIPE_SECRET_KEY || ''}` }
  );

  const awsResult = await testConnectivity(
    'AWS',
    new URL('https://aws.amazon.com/')
  );

  const logfireResult = await testConnectivity(
    'Logfire API',
    new URL('https://logfire.pydantic.dev/'),
    { 'Authorization': `Bearer ${env.LOGFIRE_TOKEN || ''}` }
  );

  // Summarize results
  console.log('\n\n=== CONNECTIVITY TEST SUMMARY ===');
  console.log(`Database URL: ${dbUrl ? 'FOUND' : 'MISSING'}`);
  console.log(`Anthropic API: ${anthropicResult.success ? '✓ REACHABLE' : '✗ UNREACHABLE'} - ${anthropicResult.message}`);
  console.log(`Stripe API: ${stripeResult.success ? '✓ REACHABLE' : '✗ UNREACHABLE'} - ${stripeResult.message}`);
  console.log(`AWS: ${awsResult.success ? '✓ REACHABLE' : '✗ UNREACHABLE'} - ${awsResult.message}`);
  console.log(`Logfire API: ${logfireResult.success ? '✓ REACHABLE' : '✗ UNREACHABLE'} - ${logfireResult.message}`);

  // Save basic results
  const results = {
    timestamp: new Date().toISOString(),
    databaseConfigured: !!dbUrl,
    endpoints: {
      anthropic: anthropicResult,
      stripe: stripeResult,
      aws: awsResult,
      logfire: logfireResult
    }
  };

  fs.writeFileSync('connectivity-test-results.json', JSON.stringify(results, null, 2));
  console.log('\nResults saved to connectivity-test-results.json');
}

main().catch(error => {
  console.error('Script failed:', error);
  process.exit(1);
});

