const express = require('express');
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');
const cors = require('cors');

const app = express();

// Security middleware
app.use(helmet()); // Sets various HTTP headers for security

// Rate limiting to prevent abuse
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.',
    code: 'TOO_MANY_REQUESTS'
  }
});

app.use(limiter);

// CORS configuration
const allowedOrigins = process.env.NODE_ENV === 'production'
  ? ['https://your-production-domain.com']
  : ['http://localhost:3000', 'http://localhost:3001'];

app.use(cors({
  origin: function (origin, callback) {
    // Allow requests with no origin (like mobile apps, curl requests)
    if (!origin) return callback(null, true);

    if (allowedOrigins.indexOf(origin) === -1) {
      const msg = 'The CORS policy for this site does not allow access from the specified origin.';
      return callback(new Error(msg), false);
    }
    return callback(null, true);
  },
  credentials: true
}));

// Input validation middleware
const validateRequest = (req, res, next) => {
  // Validate common headers
  if (req.get('Content-Length') && parseInt(req.get('Content-Length')) > 1024 * 1024) {
    return res.status(413).json({
      error: 'Payload too large',
      code: 'PAYLOAD_TOO_LARGE'
    });
  }

  // Add more validation as needed
  next();
};

app.use(validateRequest);

// Parse JSON with size limit
app.use(express.json({
  limit: '100kb'
}));

// Parse URL-encoded bodies with size limit
app.use(express.urlencoded({
  extended: true,
  limit: '100kb'
}));

// Health check endpoint
app.get('/health', (req, res) => {
  // Validate query parameters if any
  const allowedParams = ['verbose', 'detailed'];
  for (const param in req.query) {
    if (!allowedParams.includes(param)) {
      return res.status(400).json({
        error: `Invalid query parameter: ${param}`,
        code: 'INVALID_PARAMETER'
      });
    }
  }

  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      ...(req.query.verbose === 'true' && { uptime: process.uptime() })
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ 
      error: 'Internal server error',
      code: 'INTERNAL_ERROR'
    });
  }
});

// Users endpoint
app.get('/users', (req, res) => {
  try {
    // Input validation for query parameters
    const { page, limit, sortBy } = req.query;

    // Validate and sanitize pagination parameters
    const pageInt = page ? parseInt(page) : 1;
    const limitInt = limit ? parseInt(limit) : 10;

    if (isNaN(pageInt) || pageInt < 1) {
      return res.status(400).json({
        error: 'Page must be a positive integer',
