/**
 * Input validation middleware
 */
const validator = require('validator');
const createError = require('http-errors');

/**
 * Sanitize and validate string input
 */
const sanitizeString = (str) => {
  if (typeof str !== 'string') return '';
  return str.trim().substring(0, 1000); // Limit length
};

/**
 * Validate email address
 */
const validateEmail = (email) => {
  if (!email) return { valid: false, error: 'Email is required' };
  const sanitized = sanitizeString(email);
  if (!validator.isEmail(sanitized)) {
    return { valid: false, error: 'Invalid email format' };
  }
  return { valid: true, value: sanitized };
};

/**
 * Validate user ID
 */
const validateId = (id) => {
  const numId = parseInt(id, 10);
  if (isNaN(numId) || numId <= 0) {
    return { valid: false, error: 'Invalid ID format' };
  }
  return { valid: true, value: numId };
};

/**
 * Generic input cleaning
 */
const cleanInput = (input) => {
  if (Array.isArray(input)) {
    return input.map(cleanInput);
  }

  if (input && typeof input === 'object') {
    const cleaned = {};
    for (const [key, value] of Object.entries(input)) {
      // Remove potential prototype pollution vectors
      if (key !== '__proto__' && key !== 'constructor' && key !== 'prototype') {
        cleaned[key] = cleanInput(value);
      }
    }
    return cleaned;
  }

  return typeof input === 'string' ? sanitizeString(input) : input;
};

module.exports = {
  sanitizeString,
  validateEmail,
  validateId,
  cleanInput
};

/**
 * Centralized error handling middleware
 */
const createError = require('http-errors');
const logger = require('../utils/logger');

/**
 * Log error details
 */
const logError = (error, req) => {
  const errorData = {
    message: error.message,
    stack: error.stack,
    url: req.url,
    method: req.method,
    ip: req.ip,
    userAgent: req.get('User-Agent')
  };

  // Different log levels based on error type
  if (error.status >= 500) {
    logger.error('Server Error:', errorData);
  } else {
    logger.warn('Client Error:', errorData);
  }
};

/**
 * Handle errors and send appropriate responses
 */
const errorHandler = (err, req, res, next) => {
  // Log the error
  logError(err, req);

  // Set default error status
  const status = err.status || 500;

  // Don't expose stack traces in production
  const response = {
    error: {
      message: err.message || 'Internal Server Error',
      ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
    }
  };

  // Security: don't expose sensitive error details in production
  if (status === 500) {
    if (process.env.NODE_ENV === 'production') {
      response.error.message = 'Internal Server Error';
    }
  }

  res.status(status).json(response);
};

/**
 * Handle 404 errors
 */
const notFound = (req, res, next) => {
  next(createError(404, `Cannot ${req.method} ${req.url}`));
};

module.exports = {
  errorHandler,
  notFound,
  logError
};

/**
 * Simple logging utility
 * In production, consider using winston, pino, or bunyan
 */
const util = require('util');

// Simple logger with different levels
const logger = {
  info: (message, data) => {
    const log = formatLog('INFO', message, data);
    console.log(log);
  },

  warn: (message, data) => {
    const log = formatLog('WARN', message, data);
    console.warn(log);
  },

  error: (message, data) => {
    const log = formatLog('ERROR', message, data);
    console.error(log);
  },

  debug: (message, data) => {
    if (process.env.NODE_ENV === 'development') {
      const log = formatLog('DEBUG', message, data);
      console.log(log);
    }
  }
};

/**
 * Format log message
 */
function formatLog(level, message, data) {
  const timestamp = new Date().toISOString();
  const logEntry = {
    timestamp,
    level,
    message
  };

  if (data) {
    logEntry.data = data;
  }

  return JSON.stringify(logEntry);
}

module.exports = logger;

