const { cleanInput } = require('./middleware/validation');

const app = express();

// Security middleware
app.use(helmet()); // Security headers
app.use(helmet.hidePoweredBy()); // Hide Express version

// Enable CORS with restrictive policies
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',') : ['http://localhost:3000'],
  credentials: true
}));

// Request logging
app.use(morgan('dev'));

// Input size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Input cleaning middleware
app.use((req, res, next) => {
  // Clean request body, query, and params
  if (req.body) {
    req.body = cleanInput(req.body);
  }
  if (req.query) {
    req.query = cleanInput(req.query);
  }
  if (req.params) {
    req.params = cleanInput(req.params);
  }
  next();
});

// Health check - no input validation needed
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Users endpoint
