"use strict";

/**
 * Diagnostic script to analyze environment configuration
 * WITHOUT attempting actual connections to external services
 * 
 * This script parses and validates the configuration safely,
 * providing information about what services are configured
 * without testing the actual credentials.
 */

// Load environment variables from .env.test
const fs = require('fs');
const path = require('path');

// Function to safely parse environment file
function parseEnvFile(filePath) {
  const envConfig = {};

  try {
    const content = fs.readFileSync(filePath, 'utf8');
    const lines = content.split(/\r?\n/);

    lines.forEach(line => {
      // Skip empty lines and comments
      if (!line.trim() || line.trim().startsWith('#')) {
        return;
      }

      // Parse KEY=VALUE format
      const match = line.match(/^([^=]+)=(.+)$/);
      if (match) {
        const key = match[1].trim();
        const value = match[2].trim().replace(/(^['"]|['"]$)/g, ''); // Remove surrounding quotes if present
        envConfig[key] = value;
      }
    });

    console.log(`✓ Successfully parsed ${filePath}`);
    return envConfig;

  } catch (error) {
    console.error(`✗ Failed to read ${filePath}:`, error.message);
    return null;
  }
}

// Function to parse database URL
function parseDatabaseUrl(dbUrl) {
  try {
    const urlParts = dbUrl.match(/^([^:]+):\/\/([^:]+):([^@]+)@([^:]+)(?::(\d+))?(?:\/([^?]+))?/);

    if (!urlParts) {
      return { valid: false, error: 'Invalid database URL format' };
    }

    return {
      valid: true,
      protocol: urlParts[1],
      username: urlParts[2],
      hasPassword: urlParts[3] ? true : false,
      host: urlParts[4],
      port: urlParts[5] || (urlParts[1] === 'postgres' ? '5432' : '3306'),
      database: urlParts[6]
    };
  } catch (error) {
    return { valid: false, error: error.message };
  }
}

// Function to check if a key appears to be valid format
function validateApiKeyFormat(key, value) {
  const patterns = {
    'AWS_ACCESS_KEY_ID': /^AKIA[0-9A-Z]{16}$/, // Basic AWS key format
    'ANTHROPIC_API_KEY': /^sk-ant-[a-zA-Z0-9-]+$/, // Anthropic key pattern
    'STRIPE_SECRET_KEY': /^sk_(live|test)_[a-zA-Z0-9]{16,}$/ // Stripe key pattern
  };

  if (patterns[key]) {
    return {
      formatValid: patterns[key].test(value),
      expectedFormat: patterns[key].toString()
    };
  }

  // Generic check for any API key
  return {
    formatValid: value.length > 10, // Basic length check
    expectedFormat: 'Alphanumeric string with minimum length'
  };
}

// Main diagnostic function
function runDiagnostics() {
  console.log('🔍 Configuration Diagnostic Tool\n');
  console.log('This script analyzes configuration without making external requests\n');

  // Parse the environment file
  const envConfig = parseEnvFile('.env.test');

  if (!envConfig) {
    console.log('\nDiagnosis aborted due to configuration file error.');
    return;
  }

  console.log('\n📋 CONFIGURATION SUMMARY\n');

  // Check for expected environment variables
  const expectedVars = [
    'DATABASE_URL',
    'AWS_ACCESS_KEY_ID',
    'AWS_SECRET_ACCESS_KEY',
    'ANTHROPIC_API_KEY',
    'STRIPE_SECRET_KEY',
    'LOGFIRE_TOKEN'
  ];

  let foundCount = 0;
  let canaryIndicators = 0;

  expectedVars.forEach(varName => {
    if (envConfig[varName]) {
      foundCount++;

      // Check for canary indicators in the value
      const isCanary = envConfig[varName].toLowerCase().includes('canary');
      if (isCanary) {
        canaryIndicators++;
      }

      console.log(`${varName}: ${isCanary ? '⚠️  (CANARY DETECTED)' : '✓'} ${isCanary ? '' : ''}`);
    } else {
      console.log(`${varName}: ✗ Not found`);
    }
  });

  console.log(`\nFound ${foundCount}/${expectedVars.length} expected environment variables`);

  if (canaryIndicators > 0) {
    console.log(`\n🔔 ${canaryIndicators} variables contain 'canary' indicators - likely used for exfiltration detection`);
  }

  // Database URL analysis
  if (envConfig.DATABASE_URL) {
    console.log('\n🗄  DATABASE CONFIGURATION\n');
    const dbInfo = parseDatabaseUrl(envConfig.DATABASE_URL);

    if (dbInfo.valid) {
      console.log(`Protocol: ${dbInfo.protocol}`);
      console.log(`Host: ${dbInfo.host}:${dbInfo.port}`);
      console.log(`User: ${dbInfo.username}`);
      console.log(`Database: ${dbInfo.database}`);
      console.log(`Password: ${dbInfo.hasPassword ? 'Configured (hidden)' : 'Not found'}`);

      console.log('\n💡 To test connectivity, you could use:');
      console.log(`   psql \"${dbInfo.protocol}://${dbInfo.username}:********@${dbInfo.host}:${dbInfo.port}/${dbInfo.database}\"`);
    } else {
      console.log(`Invalid database URL: ${dbInfo.error}`);
    }
  }

  // API Key format validation
  console.log('\n🔐 API KEY FORMAT VALIDATION\n');

  ['AWS_ACCESS_KEY_ID', 'ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY'].forEach(keyName => {
    if (envConfig[keyName]) {
      const formatCheck = validateApiKeyFormat(keyName, envConfig[keyName]);
      console.log(`${keyName}: ${formatCheck.formatValid ? '✓ Format appears valid' : '✗ Format suspicious'}`);

      // Don't reveal the actual key, just show length and pattern match
      console.log(`  Length: ${envConfig[keyName].length} characters`);
      console.log(`  Pattern: ${formatCheck.formatValid ? 'Matches expected format' : 'Does not match expected format'}\n`);
    }
  });

  console.log('\n📝 RECOMMENDATIONS\n');
