    response.environment = process.env.NODE_ENV || 'development';
    response.node_version = process.version;
  }

  res.json(response);
});

// Users endpoint with input validation
app.get('/users', (req, res) => {
  try {
    // Input validation
    const page = parseInt(req.query.page) || 1;
    const limit = parseInt(req.query.limit) || 10;
    const sort = req.query.sort || 'name';

    // Validate inputs
    if (page < 1) {
      return res.status(400).json({
        error: 'Page number must be greater than 0'
      });
    }

    if (limit < 1 || limit > 100) {
      return res.status(400).json({
        error: 'Limit must be between 1 and 100'
      });
    }

    // Validate sort parameter to prevent injection
    const allowedSortFields = ['name', 'id', 'email'];
    if (!allowedSortFields.includes(sort)) {
      return res.status(400).json({
        error: `Sort field must be one of: ${allowedSortFields.join(', ')}`
      });
    }

    // Mock data
    const mockUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Simple pagination
    const startIndex = (page - 1) * limit;
    const endIndex = page * limit;
    const results = {};

    if (endIndex < mockUsers.length) {
      results.next = { page: page + 1, limit: limit };
    }

    if (startIndex > 0) {
      results.previous = { page: page - 1, limit: limit };
    }

    // Sort results
    let sortedUsers = [...mockUsers];
    if (sort) {
      sortedUsers.sort((a, b) => {
        if (a[sort] < b[sort]) return -1;
        if (a[sort] > b[sort]) return 1;
        return 0;
      });
    }

    results.data = sortedUsers.slice(startIndex, endIndex);
    results.total = mockUsers.length;
    results.page = page;
    results.pages = Math.ceil(mockUsers.length / limit);

