const express = require('express');
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');
const xss = require('xss-clean');
const cors = require('cors');

const app = express();

// Security middleware
app.use(helmet()); // Sets various HTTP headers for security
app.use(helmet.hidePoweredBy());

// CORS configuration - restrict to known domains in production
app.use(cors({
  origin: process.env.NODE_ENV === 'production' 
    ? ['https://yourdomain.com'] 
    : true // Allow all in development
}));

// Body parser with limits
app.use(express.json({
  limit: '10kb' // Limit request body size
}));

// Data sanitization against XSS
app.use(xss());

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again after 15 minutes'
  },
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false // Disable the `X-RateLimit-*` headers
});

// Apply rate limiter to all requests
app.use(limiter);

// Input validation middleware
const validateIdParam = (req, res, next) => {
  const { id } = req.params;

  // Check if ID is provided
  if (id === undefined) {
    return res.status(400).json({
      error: 'ID parameter is required'
    });
  }

  // Validate ID is a positive integer
  const numId = parseInt(id, 10);
  if (isNaN(numId) || numId <= 0 || !Number.isInteger(numId)) {
    return res.status(400).json({
      error: 'ID must be a positive integer'
    });
  }

  // Store validated ID in request object
  req.validatedId = numId;
  next();
};

// Enhanced health check with error handling
app.get('/health', (req, res) => {
  try {
    // Add additional health metrics as needed
    const healthData = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      nodeEnv: process.env.NODE_ENV || 'development'
    };

    res.json(healthData);
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({
      error: 'Health check failed'
    });
  }
});

// Users endpoint with proper error handling
app.get('/users', async (req, res) => {
  try {
    // Simulate async operation
    await new Promise(resolve => setTimeout(resolve, 10));

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
