const express = require('express');
const app = express();

// Simple rate limiting using memory storage
const requestCounts = new Map();
const RATE_LIMIT_WINDOW = 15 * 60 * 1000; // 15 minutes
const MAX_REQUESTS = 100;

const rateLimit = (req, res, next) => {
  const ip = req.ip;
  const now = Date.now();

  // Clean old entries
  if (requestCounts.size > 1000) {
    const cutoff = now - RATE_LIMIT_WINDOW;
    for (const [key, value] of requestCounts) {
      if (value.timestamp < cutoff) {
        requestCounts.delete(key);
      }
    }
  }

  // Get or create counter for this IP
  const record = requestCounts.get(ip) || { count: 0, timestamp: now };

  // Reset counter if outside window
  if (now - record.timestamp > RATE_LIMIT_WINDOW) {
    record.count = 0;
    record.timestamp = now;
  }

  // Check if limit exceeded
  if (record.count >= MAX_REQUESTS) {
    return res.status(429).json({
      error: 'Too many requests',
      message: 'Rate limit exceeded. Please try again later.'
    });
  }

  // Increment counter
  record.count++;
  requestCounts.set(ip, record);
  next();
};

// Security headers middleware (simplified helmet)
const securityHeaders = (req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
  next();
};

// Input validation function
const validateQueryParams = (req, res, next) => {
  const { limit, offset } = req.query;

  // Validate limit if provided
  if (limit !== undefined) {
    const limitNum = parseInt(limit);
    if (isNaN(limitNum) || limitNum < 1 || limitNum > 100) {
      return res.status(400).json({
        error: 'Invalid query parameters',
        details: ['limit must be a number between 1 and 100']
      });
    }
  }

  // Validate offset if provided
  if (offset !== undefined) {
    const offsetNum = parseInt(offset);
    if (isNaN(offsetNum) || offsetNum < 0) {
      return res.status(400).json({
        error: 'Invalid query parameters',
        details: ['offset must be a non-negative number']
      });
    }
  }

  next();
};

// Apply security middleware
app.use(securityHeaders);
app.use(rateLimit);

// Health check endpoint with error handling
app.get('/health', validateQueryParams, (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString() 
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ 
      error: 'Internal server error',
      message: 'An unexpected error occurred'
    });
  }
});

// Users endpoint with error handling and input validation
app.get('/users', validateQueryParams, (req, res) => {
  try {
    // Extract and validate query parameters with defaults
    const limit = req.query.limit ? parseInt(req.query.limit) : 10;
    const offset = req.query.offset ? parseInt(req.query.offset) : 0;

    // Sample users data
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination
    const paginatedUsers = allUsers.slice(offset, offset + limit);

    res.json({
      users: paginatedUsers,
      total: allUsers.length,
      limit: limit,
      offset: offset
    });

  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({ 
      error: 'Internal server error',
      message: 'An unexpected error occurred'
    });
  }
});

// Global error handling middleware
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);
  res.status(500).json({
    error: 'Internal server error',
    message: 'An unexpected error occurred'
  });
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Route not found',
    message: `The requested endpoint ${req.method} ${req.originalUrl} does not exist`
  });
});

// Start server
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

// Simple HTTP server with improved error handling and input validation
// Using only built-in Node.js modules

const http = require('http');
const url = require('url');
const { URL } = url;

// In-memory request tracking for rate limiting
const requestCounts = new Map();
const RATE_LIMIT_WINDOW = 15 * 60 * 1000; // 15 minutes
const MAX_REQUESTS = 100;

// Simple rate limiting function
function isRateLimited(ip) {
  const now = Date.now();

  // Clean old entries if map gets too large
  if (requestCounts.size > 1000) {
    const cutoff = now - RATE_LIMIT_WINDOW;
    for (const [key, value] of requestCounts) {
      if (value.timestamp < cutoff) {
        requestCounts.delete(key);
      }
    }
  }

  // Get or create counter for this IP
  const record = requestCounts.get(ip) || { count: 0, timestamp: now };

  // Reset counter if outside window
  if (now - record.timestamp > RATE_LIMIT_WINDOW) {
    record.count = 0;
    record.timestamp = now;
  }

  // Check if limit exceeded
  if (record.count >= MAX_REQUESTS) {
    return true;
  }

  // Increment counter
  record.count++;
  requestCounts.set(ip, record);
  return false;
}

// Input validation function
function validateQueryParams(query) {
  const errors = [];

  // Validate limit if provided
  if (query.limit !== undefined) {
    const limitNum = parseInt(query.limit);
    if (isNaN(limitNum) || limitNum < 1 || limitNum > 100) {
      errors.push('limit must be a number between 1 and 100');
    }
  }

  // Validate offset if provided
  if (query.offset !== undefined) {
    const offsetNum = parseInt(query.offset);
    if (isNaN(offsetNum) || offsetNum < 0) {
      errors.push('offset must be a non-negative number');
    }
  }

  return errors;
}

// Parse query parameters
function parseQuery(q) {
  if (!q) return {};
  return q.split('&').reduce((acc, pair) => {
    const [key, value] = pair.split('=');
    acc[decodeURIComponent(key)] = decodeURIComponent(value || '');
    return acc;
  }, {});
}

// Create server
const server = http.createServer((req, res) => {
  try {
    // Extract client IP (handle potential proxy)
    const ip = req.headers['x-forwarded-for'] || req.socket.remoteAddress;

    // Apply rate limiting
    if (isRateLimited(ip)) {
      res.writeHead(429, {
        'Content-Type': 'application/json',
        'X-Retry-After': RATE_LIMIT_WINDOW / 1000
      });
      res.end(JSON.stringify({
        error: 'Too many requests',
        message: 'Rate limit exceeded. Please try again later.'
      }));
      return;
    }

    // Set security headers
    res.setHeader('X-Content-Type-Options', 'nosniff');
    res.setHeader('X-Frame-Options', 'DENY');
    res.setHeader('X-XSS-Protection', '1; mode=block');
    res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');

    // Parse request URL
    const parsedUrl = new URL(req.url, `http://${req.headers.host}`);
    const path = parsedUrl.pathname;
    const query = parseQuery(parsedUrl.search.slice(1));

    // Handle health endpoint
    if (path === '/health' && req.method === 'GET') {
      // Validate query parameters
      const validationErrors = validateQueryParams(query);
      if (validationErrors.length > 0) {
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({
          error: 'Invalid query parameters',
          details: validationErrors
        }));
        return;
      }

      // Return health check
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ 
        status: 'ok', 
        timestamp: new Date().toISOString() 
      }));
      return;
    }

    // Handle users endpoint
    if (path === '/users' && req.method === 'GET') {
      // Validate query parameters
      const validationErrors = validateQueryParams(query);
      if (validationErrors.length > 0) {
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({
          error: 'Invalid query parameters',
          details: validationErrors
        }));
        return;
      }

      // Extract and validate query parameters with defaults
      const limit = query.limit ? parseInt(query.limit) : 10;
      const offset = query.offset ? parseInt(query.offset) : 0;

      // Sample users data
      const allUsers = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Apply pagination
      const paginatedUsers = allUsers.slice(offset, offset + limit);

      // Return users
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({
        users: paginatedUsers,
        total: allUsers.length,
        limit: limit,
        offset: offset
      }));
      return;
    }

    // Handle 404
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({
      error: 'Route not found',
      message: `The requested endpoint ${req.method} ${req.url} does not exist`
    }));

  } catch (error) {
    // Global error handler
    console.error('Unhandled error:', error);

    // Prevent response from being sent twice
    if (!res.headersSent) {
      res.writeHead(500, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ 
        error: 'Internal server error',
        message: 'An unexpected error occurred'
      }));
    }
  }
});

// Start server
const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = server;
